"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[967],{8436:function(e,t,o){o.d(t,{bw:function(){return a},Zf:function(){return s}});let n=[{id:"com-d01",month:1,week:1,day:1,dayIndex:1,type:"reading",title:"Why Talking Feels Hard (It’s Not You)",duration:"10 min",summary:"Speaking up can feel like standing on a tall ladder. Today’s stories show why — and why it is the ladder, not you.",concepts:["Speaking anxiety","Spotlight effect","Threat response"],tryOn:'Say one prepared sentence out loud today in a low-stakes place. Use these exact words anywhere they fit: "That sounds interesting — could you say more?" Nothing rides on this sentence. The win is the saying.',cards:[{kind:"hook",body:"Talking feels hard because your brain treats a room full of people like a room full of lions. It is protecting you — from the wrong thing."},{kind:"story",title:"Tobi and the meeting",body:'Tobi had an idea in the Tuesday meeting. For nine minutes he rehearsed it in his head. The words were perfect — in his head. When his turn came, he said "nothing from me" and spent the rest of the meeting annoyed at himself. That evening he told his sister the idea. She said: "That’s really good. Why didn’t you say it?" Great question. And the answer is not that Tobi is broken.'},{kind:"text",title:"The ladder in your head",body:"When you speak in front of people, your brain runs the same alarm it runs for real danger: faster heart, dry mouth, blank mind. Psychologists call it a threat response. Useful when lions are present. In a meeting it is a false alarm — but your body does not know that yet. Today we start teaching it."},{kind:"definition",title:"Spotlight effect",body:"The feeling that everyone is watching you closely. Research shows they are watching far less than it feels."},{kind:"story",title:"The two-minute spotlight",body:'Amara tripped on the last stair at work and felt everyone’s eyes on her all morning. At lunch she mentioned it, embarrassed. Her colleague frowned: "What stair?" The spotlight that had been burning on her all morning had barely flickered for anyone else. Your awkward moment is a background detail in other people’s days.'},{kind:"text",title:"What this means for you",body:"Three things follow. One: the fear is real, but the danger is not. Two: other people notice less than you think. Three: courage is not the absence of the ladder feeling — it is speaking while the ladder is still there. Today’s try-on is one sentence while standing on it."},{kind:"practice",title:"Practice task",body:'Pick the place for your try-on now: a shop, a family member, a chat thread. Deciding early doubles your odds. And remember the sentence: "That sounds interesting — could you say more?"'}],questions:[{kind:"mcq",question:"Why does speaking up feel physically dangerous?",options:["The brain runs a threat response, like it would for real danger","Because speaking is actually dangerous","Because you are not good at talking","Because your lungs are working wrong"],answer:0,explanation:"It is a false alarm — protective machinery firing in a safe room. The feeling is real; the danger is not.",concept:"Threat response"},{kind:"truefalse",question:"The spotlight effect means everyone really is watching you closely.",options:["True","False"],answer:1,explanation:"It only feels that way. Other people are busy with their own staircases.",concept:"Spotlight effect"},{kind:"scenario",question:'Tobi has an idea but says "nothing from me." What is the most useful first step?',options:["Say one prepared sentence in a low-stakes place to practise speaking while nervous","Wait until he never feels nervous","Send anonymous notes forever","Quit meetings"],answer:0,explanation:"Courage grows by speaking while the ladder feeling is present — tiny sentences count.",concept:"Speaking anxiety"}],share:{hook:"Courage is speaking while the ladder is still there.",question:"What is one low-stakes sentence you could say this week?",posts:{reflective:'Day 1 of Uneek Academy’s communication course told two stories that felt uncomfortably familiar. Tobi rehearsed an idea for nine minutes and said nothing. Amara tripped on a stair and felt watched all morning — her colleague never noticed. The lesson: speaking up triggers a threat response built for lions, and the spotlight effect exaggerates everyone else’s attention. The fear is real; the danger is not. My try-on today was one prepared sentence in a shop: "That sounds interesting — could you say more?" Small, awkward, and weirdly powerful. What is one low-stakes sentence you could say this week?',direct:'Speaking up feels dangerous because your brain runs a threat response built for lions. Day 1 of Uneek Academy’s communication course. Add the spotlight effect — the false feeling that everyone is watching — and silence becomes logical. But silence has a cost. The fix is not fearlessness; it is one prepared sentence in a low-stakes place: "That sounds interesting — could you say more?" Today I said it. Nervous, fine, done. What is one low-stakes sentence you could say this week?',story:'In Tuesday’s meeting Tobi had a good idea and said "nothing from me." That evening his sister asked the painful question: "Why didn’t you say it?" Day 1 of Uneek Academy’s communication course explains why — and it is not that Tobi is broken. The brain treats speaking up like standing near a lion, and the spotlight effect makes everyone look like a judge. The fear is real; the danger is not. Today’s try-on: one sentence, low stakes, out loud. I chose "That sounds interesting — could you say more?" What is one sentence you could say this week?'}}},{id:"com-d02",month:1,week:1,day:2,dayIndex:2,type:"video",title:"The Words That Come Out Wrong",duration:"8 min",summary:"What you mean and what people hear are two different sentences. Today: how to make them match.",concepts:["Message vs. reception","Clarity","Tone"],tryOn:'Send one message today that you reread once before sending. Check only one thing: could any sentence be read in a grumpy tone? If yes, add a softener. Example: "Does Thursday work?" → "Would Thursday work for you?"',cards:[{kind:"hook",body:"You send a message. It arrives as a completely different message. Nobody is lying — translation just happened without you."},{kind:"story",title:"The shortest text in history",body:'Chidi sent his team: "We need to talk about the report." Four words. Within an hour, two people were polishing their CVs. He had meant: "Let’s improve the report together." What he wrote sounded like a verdict. The words were his; the fear in them was everyone else’s imagination — invited by his wording.'},{kind:"text",title:"Message vs. reception",body:"Every message is received twice: what you meant, and what it sounds like. Tone, wording, and context do the translating. You cannot fully control reception — but you can write sentences that leave less room for the scary reading."},{kind:"definition",title:"Tone in writing",body:"The emotional colour your words carry to the reader — often darker or sharper than you intended."},{kind:"example",title:"Everyday example",body:'"Fine." vs "Sounds good!" vs "Sure thing." All mean yes. All land differently. The fix is not emoji (though they help); it is specific, warm wording: "Would Thursday work for you?" beats "Does Thursday work?" by a mile.'},{kind:"practice",title:"Practice task",body:"Use today’s try-on on one real message. Keep the receipt: screenshot before/after. You are building a habit of reading your words as if you were the other person."}],questions:[{kind:"mcq",question:"Why can a neutral message be received as hostile?",options:["The reader fills in tone the writer never intended","The internet corrupts text","Readers are usually unkind","Capital letters change meaning"],answer:0,explanation:"Reception is a translation. Leave less room for the scary reading with warm, specific wording.",concept:"Message vs. reception"},{kind:"truefalse",question:'"We need to talk about the report" is a neutral way to open a collaboration.',options:["True","False"],answer:1,explanation:'It reads like a verdict. "Let’s improve the report together" says the same intent without the chill.',concept:"Tone"},{kind:"scenario",question:"Which is the clearest, warmest way to ask about timing?",options:['"Would Thursday work for you?"','"Does Thursday work?"','"Thursday."','"You probably can’t do Thursday."'],answer:0,explanation:"Specific, polite, and easy to answer. Clarity is kindness to the reader.",concept:"Clarity"}],share:{hook:"You send a message. It arrives as a different message.",question:"What is one message you could rewrite to land kinder?",posts:{reflective:'Day 2 of Uneek Academy’s communication course: "We need to talk about the report." Four words, and two teammates were polishing their CVs. The writer meant "let’s improve it together"; the readers heard a verdict. Messages are received twice — what you meant, and what it sounds like. The exercise was small and surprisingly useful: reread one message before sending and ask, could this be read in a grumpy tone? I changed "Does Thursday work?" to "Would Thursday work for you?" The whole sentence relaxed. What is one message you could rewrite to land kinder?',direct:'Your message is received twice: what you meant, and what it sounds like. Day 2 of Uneek Academy’s communication course. "We need to talk about the report" meant "let’s improve it" — it read like a firing. The fix takes ten seconds: reread before sending and warm one sentence. "Would Thursday work for you?" instead of "Does Thursday work?" Clarity is kindness to the reader. What is one message you could rewrite to land kinder?',story:'My friend sent his team "we need to talk about the report" and spent the afternoon calming two people who thought they were in trouble. He meant: let’s make it better. Day 2 of Uneek Academy’s communication course called it message vs. reception — the words were his, the fear was invited by his wording. My try-on: reread one message before sending, warm one sentence. "Does Thursday work?" became "Would Thursday work for you?" Small edit, different weather. What is one message you could rewrite to land kinder?'}}},{id:"com-d03",month:1,week:1,day:3,dayIndex:3,type:"interactive",title:"The 3-Second Pause",duration:"8 min",summary:"Between what happens and what you say, there is a gap. Practice makes the gap big enough to choose in.",concepts:["Response gap","Pausing","Composure"],tryOn:'Use a 3-second pause before answering any question today. Count it quietly: "one, two, three" — then speak. Timid version: the pause actually makes you sound thoughtful, not slow. That is the trick.',cards:[{kind:"hook",body:"Between what happens and what you say, there is a gap. Most people never find it. Today you find it — and stand in it."},{kind:"story",title:"The gap that saved a conversation",body:'Someone asked Ifeoma, "So do you actually know how to do this?" The old Ifeoma would have snapped back or shrunk. New Ifeoma — three days into practising pauses — counted "one, two, three" and said, "I’m still learning it. What would you like to see first?" The question was rude. The answer was calm. The three seconds did that.'},{kind:"text",title:"Why three seconds",body:"Your first reaction forms in about one second — usually the defensive one. Three seconds is enough for the thoughtful one to catch up. In that gap you can choose tone, choose words, or choose silence. The pause also makes you look composed: audiences read it as confidence."},{kind:"definition",title:"Response gap",body:"The small space between a trigger and your reply — trainable, and where most of communication is actually won."},{kind:"example",title:"Everyday example",body:'In the scenarios below, notice how the pause changes every outcome. "Are you free Saturday?" (pause → you check your actual weekend). "This is wrong." (pause → you ask which part, instead of defending everything).'},{kind:"practice",title:"Practice task",body:"Before today’s try-on, practise the pause alone: ask yourself a question out loud, count three, answer. It feels silly for ten seconds. Then it feels like a superpower."}],questions:[{kind:"scenario",question:'Someone says, "So do you actually know how to do this?" What is the pause for?',options:["To let a calm, chosen answer arrive instead of a defensive one","To make them uncomfortable","To remember the words","To decide whether to leave"],answer:0,explanation:"The gap is where tone and wording become choices instead of reflexes.",concept:"Response gap"},{kind:"mcq",question:"How do audiences usually read a 3-second pause?",options:["As composure and thoughtfulness","As confusion","As weakness","As rudeness"],answer:0,explanation:"The pause that helps you also signals confidence to the room.",concept:"Composure"},{kind:"truefalse",question:"Your first reaction is usually the most thoughtful one.",options:["True","False"],answer:1,explanation:"The first reaction is the fast, defensive one. The thoughtful one arrives a beat later.",concept:"Pausing"}],share:{hook:"Between what happens and what you say, there is a gap. Stand in it.",question:"Where would a 3-second pause have helped you this week?",posts:{reflective:'Day 3 of Uneek Academy’s communication course gave me one of the smallest and most useful tools I have tried: a 3-second pause. Between a trigger and your reply there is a gap — one second brings the defensive reaction, three seconds brings the thoughtful one. A story in the lesson: someone asked "do you actually know how to do this?" and the answer after a pause was calm instead of sharp. My try-on was pausing before every answer today. Nobody noticed the pause. Two people told me I seemed thoughtful. Where would a 3-second pause have helped you this week?',direct:'The 3-second pause is the cheapest upgrade in communication. Day 3 of Uneek Academy’s course. One second delivers the defensive reply; three seconds delivers the chosen one — and the pause reads as composure, not slowness. Today I counted "one, two, three" before answering anything. Two people said I seemed thoughtful. That is the trick: the pause helps you and flatters you at once. Where would it have helped you this week?',story:'A colleague asked me, a little sharply, "so do you actually know how to do this?" Old me would have snapped or shrunk. This week — day 3 of Uneek Academy’s communication course — I counted one, two, three and said "I’m still learning it. What would you like to see first?" The question was rude; the answer was calm. The three seconds did that. My try-on is now a daily habit: pause before every answer. Where would a 3-second pause have helped you this week?'}}},{id:"com-d04",month:1,week:1,day:4,dayIndex:4,type:"reading",title:"Say It So People Can Hear It",duration:"9 min",summary:"Clear beats clever. Today’s tool: one simple structure that makes anything you say easier to follow.",concepts:["Clarity","Structure","What–So What–Now What"],exercise:"Rewrite one real thing you need to say this week using the What–So What–Now What structure. Keep it under three sentences. Test it on a friend, a mirror, or a voice note.",tryOn:'Find one thing you need to say this week (a request, an update, an opinion). Write it in three lines: "What: ___. So what: ___. Now what: ___." Read it aloud once. Notice how much shorter it is than what you had planned to say.',cards:[{kind:"hook",body:"People do not fail to hear you because your idea is bad. They fail because it arrived as a pile instead of a path."},{kind:"story",title:"The five-minute answer",body:'In her review, Grace was asked "How is the project going?" She talked for five minutes about vendor delays, the new intern, and a bug from March. Her manager’s face slowly went blank. Afterwards her mentor asked one question: "What did you want them to know?" Grace thought: "That we’ll be two weeks late." Five minutes to deliver one sentence. It is not nerves this time — it is structure.'},{kind:"text",title:"What–So What–Now What",body:'Anything you say lands better in three moves: What (the facts), So what (why it matters), Now what (what happens next). "We’ll be two weeks late (what) — the launch misses the school term (so what) — I suggest we ship the reading feature first (now what)." Three lines. A person can repeat that.'},{kind:"definition",title:"What–So What–Now What",body:"A three-part structure: the facts, why they matter, and what happens next."},{kind:"example",title:"Everyday example",body:'Asking for help: "What: I’m stuck on the budget sheet. So what: it blocks Friday’s numbers. Now what: could you spare 15 minutes today?" Compare with the usual five-minute fog. Same request, actually answerable.'},{kind:"practice",title:"Practice task",body:"Run today’s exercise on a real message. Bonus rule of thumb: if a sentence does not fit What, So what, or Now what, it is probably a pile — take it out."}],questions:[{kind:"mcq",question:"Grace’s five-minute answer failed because…",options:["It lacked structure — the key point was buried","Her idea was bad","She was not smart enough","Her manager was rude"],answer:0,explanation:"A pile of facts hides the one sentence people need. Structure is the rescue.",concept:"Structure"},{kind:"mcq",question:'"So what" in the structure means…',options:["Why the facts matter to this listener","What happens next","The facts themselves","An apology"],answer:0,explanation:"What = facts. So what = relevance. Now what = next step.",concept:"What–So What–Now What"},{kind:"scenario",question:"Which request is clearest?",options:['"I’m stuck on the budget sheet; it blocks Friday’s numbers; could you spare 15 minutes today?"','"So… about the thing… there’s a lot going on…"','"Can I ask a small favour? It’s complicated."','"Never mind, I’ll manage."'],answer:0,explanation:"What, so what, now what — in one breath, and fully answerable.",concept:"Clarity"}],share:{hook:"Clear beats clever. Structure is how you get clear.",question:"What is one thing you could say in three lines instead of five minutes?",posts:{reflective:'Day 4 of Uneek Academy’s communication course fixed a habit I did not know I had: the five-minute fog. The lesson’s story — asked "how is the project going?", one person talked for five minutes and delivered one sentence — felt like watching myself. The tool is What–So What–Now What: facts, why they matter, next step. I rewrote a real request in three lines and said it out loud in fifteen seconds. It was answered in thirty. What is one thing you could say in three lines instead of five minutes?',direct:'Stop talking for five minutes to deliver one sentence. Day 4 of Uneek Academy’s communication course: use What–So What–Now What. The facts, why they matter, what happens next. "We’ll be two weeks late — the launch misses the school term — let’s ship the reading feature first." That is answerable. I tested it on a real request: 15 seconds to say, 30 to answer. What is one thing you could say in three lines instead of five minutes?',story:'My manager asked "how is the project going?" and I talked for five minutes about vendors, interns, and a bug from March. Afterwards I wrote the one thing I had wanted them to know: "We’ll be two weeks late." Day 4 of Uneek Academy’s communication course gave me the fix — What, So What, Now What. I rewrote my next request in three lines and it took fifteen seconds to say. What is one thing you could say in three lines instead of five minutes?'}}},{id:"com-d05",month:1,week:1,day:5,dayIndex:5,type:"reading",title:"Your First Brave Sentence",duration:"9 min",summary:"Bravery scales. Today is about the smallest possible acts of speaking up — with exact words, for people who hate speaking up.",concepts:["Micro-bravery","Scripts","Speaking up"],exercise:"Choose one brave sentence from today’s list and use it in the wild this week. Write the line down, put it in your notes app, and deploy it when the moment comes. Note what happened.",tryOn:'Pick ONE script and say it today. (1) "Actually, I’d prefer tea, thanks." (2) "Could I add one thing?" (3) "I disagree — here’s why." (4) "Could you repeat that? I want to get it right." Each is under eight words. The size is the point.',cards:[{kind:"hook",body:"Bravery is not a personality. It is a size. Shrink it small enough and anyone can carry it."},{kind:"story",title:"The tea test",body:'Zainab’s communication coach did not start with speeches. The first assignment: order tea — and say "Actually, I’d prefer tea, thanks" when they brought coffee by mistake. Zainab practised the sentence in her car. She said it at the caf\xe9. The waiter said "no problem." That was the whole event. But something shifted: a sentence she used to swallow, said out loud, and the world did not end. Week after week the sentences grew. That is how it actually works.'},{kind:"text",title:"The micro-bravery ladder",body:'Speaking up is a muscle, not a switch. Start with zero-audience sentences (ordering, small preferences), then tiny-audience sentences ("could I add one thing?" with one friend), then real ones (a disagreement in a meeting). Each rung is a sentence under ten words. Timid people do not need bigger courage — they need smaller first rungs.'},{kind:"definition",title:"Micro-bravery",body:"A deliberately tiny act of speaking up — small enough that your threat system lets you do it."},{kind:"list",title:"The brave-sentence kit (say one today)",items:['"Actually, I’d prefer tea, thanks." — preferences, zero stakes.','"Could I add one thing?" — entering a conversation.','"I disagree — here’s why." — opinions, one-on-one first.','"Could you repeat that? I want to get it right." — when jokes sting.','"No, thank you." — the complete sentence. No essay required.']},{kind:"practice",title:"Practice task",body:'Run today’s exercise: one script in the wild this week. Report card is one line: what you said, what happened. Expect the answer to be "nothing bad." That expectation update is the real lesson.'}],questions:[{kind:"mcq",question:"Why start with tiny sentences like ordering tea?",options:["Small enough that the threat system allows them — bravery grows from there","To waste time before real talk","Because waiters need practice too","Because big sentences are banned"],answer:0,explanation:"Shrink the task until it fits under your fear. Then grow it.",concept:"Micro-bravery"},{kind:"truefalse",question:"Timid people need bigger courage before they can speak up.",options:["True","False"],answer:1,explanation:"They need smaller first rungs. The courage was never the missing part.",concept:"Speaking up"},{kind:"scenario",question:"Someone makes a stinging joke at your expense. Which script fits?",options:['"Could you repeat that? I want to get it right."',"Laugh along and hurt later",'"Nothing from me."',"Send a long text that night"],answer:0,explanation:"It is calm, under eight words, and passes the joke back to its owner.",concept:"Scripts"}],share:{hook:"Bravery is not a personality. It is a size.",question:"What is the smallest brave sentence you could say today?",posts:{reflective:'Day 5 of Uneek Academy’s communication course: the tea test. The first assignment was not a speech — it was correcting an order: "Actually, I’d prefer tea, thanks." One sentence, practised in a car, said to a waiter, answered with "no problem." That is the micro-bravery ladder: sentences under ten words, growing rung by rung. Timid people don’t need bigger courage; they need smaller first rungs. I ran my sentence today. Nothing bad happened — which is exactly the data I needed. What is the smallest brave sentence you could say today?',direct:'Bravery is a size, not a personality. Day 5 of Uneek Academy’s communication course. Start where your threat system won’t fight you: "Actually, I’d prefer tea, thanks." Then "Could I add one thing?" Then "I disagree — here’s why." Under ten words each, in order. I used one today. The world did not end; it rarely does. Timid people don’t need bigger courage — they need smaller first rungs. What is the smallest brave sentence you could say today?',story:'My friend’s first communication assignment was absurd: order tea, let them bring coffee, and say "Actually, I’d prefer tea, thanks." She practised it in the car. The waiter said "no problem." That was the whole event — and it changed something. Day 5 of Uneek Academy’s communication course names it: micro-bravery. Sentences under ten words, growing rung by rung. I tried "Could I add one thing?" in a meeting today. It worked. What is the smallest brave sentence you could say today?'}}},{id:"com-d06",month:1,week:1,day:6,dayIndex:6,type:"review",title:"Week 1 Review: Speaking Without Shrinking",duration:"10 min",summary:"Five tools, one week: threat response, the spotlight effect, the pause, What–So What–Now What, and micro-bravery.",concepts:["Week 1 synthesis"],reviewTopics:["Threat response","Spotlight effect","The 3-second pause","What–So What–Now What","Micro-bravery"],tryOn:"Teach one of this week’s five ideas to a person — or to a voice note. Use a real example from your week. If you stumble on one idea, that is your review list.",cards:[{kind:"hook",body:"One week ago, speaking up was a personality trait. Now it is a set of tools — and tools can be picked up."},{kind:"list",title:"This week’s five concepts",items:["Threat response — the ladder feeling is a false alarm, not a verdict.","Spotlight effect — everyone is watching less than it feels.","The 3-second pause — the gap where chosen words live.","What–So What–Now What — facts, why they matter, next step.","Micro-bravery — sentences under ten words, rung by rung."]},{kind:"text",title:"How they fit together",body:"The pause buys you time when the threat system fires. Structure gives the words a shape. Micro-bravery is how you practise safely. The spotlight effect is the reminder that the risk is smaller than it feels. Together: a quiet person with tools."},{kind:"practice",title:"Before the quiz",body:"Say the five concepts out loud once. Whichever one you cannot say without looking is the one the quiz will ask about first."}],questions:[{kind:"mcq",question:"The ladder feeling when speaking up comes from…",options:["A threat response built for real danger","A character flaw","Poor vocabulary","The audience being hostile"],answer:0,explanation:"False alarm, real feeling. You can speak while it rings.",concept:"Threat response"},{kind:"mcq",question:"The spotlight effect says that…",options:["People watch you less closely than it feels","Everyone is judging you carefully","Lights should face the speaker","You should avoid attention"],answer:0,explanation:"Your awkward moment is a background detail in other people’s days.",concept:"Spotlight effect"},{kind:"mcq",question:"The 3-second pause is valuable because…",options:["The thoughtful response arrives a beat after the defensive one","It confuses listeners","It fills silence","It is required by etiquette"],answer:0,explanation:"One second = reflex. Three seconds = choice.",concept:"The 3-second pause"},{kind:"mcq",question:'"So what" in What–So What–Now What stands for…',options:["Why the facts matter to the listener","The facts","The next step","An apology"],answer:0,explanation:"What = facts. So what = relevance. Now what = next step.",concept:"What–So What–Now What"},{kind:"mcq",question:"Micro-bravery means…",options:["Deliberately tiny acts of speaking up","Speaking less","Pretending to be brave","Big speeches in small rooms"],answer:0,explanation:"Shrink the task until it fits under your fear. Then grow it.",concept:"Micro-bravery"},{kind:"truefalse",question:"A 3-second pause makes you look slow and uncertain.",options:["True","False"],answer:1,explanation:"Audiences read it as composure. It helps you and flatters you.",concept:"The 3-second pause"},{kind:"truefalse",question:"Tone in writing can change how neutral words are received.",options:["True","False"],answer:0,explanation:"Messages are received twice. Warm, specific wording shrinks the gap.",concept:"Threat response"},{kind:"scenario",question:"You must tell your team the launch slips two weeks. Best structure?",options:["What (two weeks late) → So what (misses the school term) → Now what (ship the reading feature first)","Five minutes of background first",'"It’s complicated, we’ll see."',"An apology, then silence"],answer:0,explanation:"Three lines a person can repeat. Clarity is kindness.",concept:"What–So What–Now What"}],share:{hook:"Speaking up is not a personality. It is a set of tools.",question:"Which of the week’s five tools will you carry into next week?",posts:{reflective:"Week 1 of Uneek Academy’s communication course done. Five tools: the threat response is a false alarm, the spotlight effect exaggerates attention, the 3-second pause creates choice, What–So What–Now What creates clarity, and micro-bravery creates momentum. Two try-ons surprised me: a pause that made me sound thoughtful, and a small preference said out loud with no disaster. I am not suddenly loud. I am no longer silent. Which of the five tools will you carry into next week?",direct:"Week 1 of Uneek Academy’s communication course complete. The toolkit: threat response (false alarm), spotlight effect (they’re not watching), 3-second pause (choice), What–So What–Now What (clarity), micro-bravery (momentum). Practical result this week: one corrected order, one added opinion, one clear request. Quiet, not silenced. Which tool are you carrying into next week?",story:'Seven days ago my friend would have said she is "just shy." Tonight she corrected an order — "Actually, I’d prefer tea, thanks" — and told a three-line story about her week without apologising once. Week 1 of Uneek Academy’s communication course: the ladder feeling is a false alarm, the spotlight is dimmer than it feels, the pause is a superpower, structure beats fog, and bravery is a size. Which of the five tools will you carry into next week?'}}},{id:"com-d07",month:1,week:1,day:7,dayIndex:7,type:"rest",title:"Rest Day",duration:"1 min",summary:"Rest is part of the program, not a break from it.",concepts:[],cards:[],questions:[],restMessage:"Your voice has practised enough for one week. Today: no exercises, no scripts. Let it settle. Tick rest below and the streak keeps rolling.",share:{hook:"Rest is where learning settles.",posts:{reflective:"",direct:"",story:""}}}],i=[{id:"psy-d01",month:1,week:1,day:1,dayIndex:1,type:"reading",title:"What Psychology Actually Is",duration:"10 min",summary:"Psychology is not mind-reading or Freud on a couch. It is the careful study of how people think, feel, and behave — told today through two small stories you will recognize.",concepts:["What psychology is","Patterns of behaviour","Science of the mind"],tryOn:'Find one conversation today — any conversation. Afterwards, write one line: "They said ___ but I noticed ___." That is your first data point. (Quiet version: just listen to a call or a show and note it privately. Nothing to say out loud yet.)',cards:[{kind:"hook",body:"Psychology is not about reading minds. It is about noticing patterns."},{kind:"story",title:"The two conversations",body:'Amara had two conversations last Monday. First, her friend said "I’m fine" while closing her phone and dropping her voice. Amara shrugged and changed the subject. Second, her little cousin said "I hate school" and Amara asked, "What happened today?" — and got the real story: a spelling test went badly. Same Amara. Two conversations. In one she heard words; in the other she heard a pattern. Psychology is the second way of listening.'},{kind:"text",title:"So what is it?",body:'Psychology is the study of how people think, feel, and behave. Not guesses or horoscopes — careful observation. Psychologists watch what people do, form a guess about why, and then test that guess. The "why" part is what makes it powerful.'},{kind:"definition",title:"Psychology",body:"The careful study of how people think, feel, and behave — and why."},{kind:"story",title:'The pattern behind "I’m fine"',body:"Think again about Amara’s friend. The words said fine; the tone said otherwise. A psychologist does not guess her whole childhood from one sentence. They simply notice the gap between words and behaviour — and stay curious. Over a week, that curiosity might reveal a pattern: she goes quiet whenever work comes up. One observation is a data point. Three observations is a pattern. A pattern is where psychology begins."},{kind:"example",title:"Everyday example",body:'You wave at a friend and they do not wave back. The instant sentence in your head: "They’re ignoring me." That sentence is a guess about behaviour. Psychology teaches you to hold it loosely: maybe they did not see you. Same event, different reading — and a much different evening.'},{kind:"practice",title:"Practice task",body:"Before today’s try-on, do this warm-up: watch one conversation — at home, in class, or on a call. Notice one thing someone did that did not match what they said. That’s it. You just collected your first data point."}],questions:[{kind:"mcq",question:"Which is the best definition of psychology?",options:["The careful study of how people think, feel, and behave","The ability to know what someone is thinking without asking","Advice about how to live a better life","The study of the brain’s cells and chemicals only"],answer:0,explanation:"Psychology studies thoughts, feelings, and behaviour — carefully, and with tests, not guesses.",concept:"What psychology is"},{kind:"truefalse",question:"Psychology relies mainly on guessing what people are thinking.",options:["True","False"],answer:1,explanation:'Psychologists observe and test. The word "guess" is the opposite of the whole method.',concept:"Science of the mind"},{kind:"scenario",question:'A colleague says "Great idea" but immediately starts finding problems with it. What is the psychological move?',options:["Assume they are jealous of you","Notice the gap between their words and behaviour and get curious about it","Tell them to stop being negative","Ignore everything and move on"],answer:1,explanation:"Psychology starts with noticing the mismatch, then staying curious — not jumping to conclusions.",concept:"Patterns of behaviour"}],share:{hook:"Psychology is not about reading minds. It is about noticing patterns.",question:"What is one pattern in your own behaviour you have never questioned?",posts:{reflective:'I used to think psychology was about reading minds. Day 1 of Uneek Academy taught me it is closer to gardening: noticing what grows, and under what conditions. The lesson followed two conversations — one where "I’m fine" was just words, and one where asking "what happened?" revealed a spelling test that went badly. The gap between what people say and what they do is where the real information lives. Today I watched one conversation and noticed a mismatch between words and tone. It is a small habit, but it already changes how I listen. Question for you: what is one pattern in your own behaviour you have never questioned?',direct:'Psychology is not mind-reading. It is pattern-noticing. That is the first lesson of Uneek Academy’s psychology course, and it lands hard. The method is simple: observe behaviour, form a guess, test the guess. No horoscopes, no guessing what people think. The most useful signal is the gap between what someone says and what they do — "I’m fine" said in a flat voice. Today’s task: watch one conversation and record one mismatch. One data point a day beats a shelf of unread books. What pattern in your own behaviour have you never questioned?',story:'Last Monday my friend said "I’m fine" while closing her phone and dropping her voice. Old me shrugged and changed the subject. That same evening, my little cousin said "I hate school" and I asked "what happened today?" — and got the real story. Day 1 of Uneek Academy’s psychology course named the difference: psychology is not reading minds, it is noticing patterns. The gap between words and behaviour is where the real information lives. My try-on today: one conversation, one mismatch, one note. What is one pattern in your own behaviour you have never questioned?'}}},{id:"psy-d02",month:1,week:1,day:2,dayIndex:2,type:"video",title:"Your Brain on Autopilot",duration:"8 min",summary:"Most of your day runs on mental autopilot. That is not laziness — it is your brain saving energy for what matters.",concepts:["Automatic processing","Mental energy","Conscious control"],tryOn:"Redo one tiny routine today as if it were your first time — tea, tying laces, the walk to your door. Count the steps in your head and note the one step autopilot always hides from you.",cards:[{kind:"hook",body:"You drove or walked a familiar route today and remember almost none of it. That is not a failure. That is the design."},{kind:"text",title:"Two systems, one brain",body:"Your brain runs a lot of actions automatically: walking, reading faces, tying laces. Automatic processing is fast, effortless, and mostly invisible. Conscious control is slow, effortful, and tiring. Your brain uses it sparingly — like a phone that dims the screen to save battery."},{kind:"definition",title:"Automatic processing",body:"Mental work your brain does quickly and without effort because it has practised it before."},{kind:"example",title:"Everyday example",body:"Think about the first time you cooked rice versus now. Then, every step needed attention. Now you do it while talking. The effort did not disappear — it moved into autopilot. This is why experts look calm: their basics are automatic."},{kind:"practice",title:"Practice task",body:"Pick one routine you do daily (brushing teeth, a commute, making tea). Do it once today as if it were your first time. Notice how many tiny steps autopilot was hiding from you."}],questions:[{kind:"mcq",question:"Why does the brain use automatic processing?",options:["To save mental energy for harder problems","Because it is lazy and refuses to think","To make everything slower and safer","Because conscious thought is impossible"],answer:0,explanation:"Automatic processing is efficiency: practised actions run quietly so attention is free for what is new or hard.",concept:"Automatic processing"},{kind:"truefalse",question:"Conscious control is fast and effortless.",options:["True","False"],answer:1,explanation:"Conscious control is slow and effortful — that is exactly why the brain reserves it.",concept:"Conscious control"},{kind:"scenario",question:"You arrive at work and cannot remember the drive. What is the best explanation?",options:["Your memory is failing","The drive was handled by automatic processing, so little needed conscious attention","You were probably asleep","You are too stressed to function"],answer:1,explanation:"Familiar actions run on autopilot. When nothing surprising happens, little of it gets stored.",concept:"Automatic processing"}],share:{hook:"Your brain is not lazy. It is running a power-saving mode.",question:"Which part of your day would you like to bring back from autopilot?",posts:{reflective:'Day 2 of Uneek Academy’s psychology course: your brain has a power-saving mode. Walking, reading faces, making tea — these run on automatic processing so your attention is free for what is new or hard. Conscious control is the expensive resource; the brain spends it carefully. The exercise was to redo one routine as if it were my first time. I tried making tea slowly and found eleven steps autopilot had been hiding. It reframes "being on autopilot" as efficiency, not failure — and it asks a nice question: what would you like to bring back from autopilot into the light?',direct:"Your brain runs a power-saving mode. Day 2 of a psychology course, and this is the most useful thing I learned this week. Familiar actions — walking, tea, commuting — run on automatic processing so conscious effort can be spent on what actually matters. That is why you cannot remember your commute: nothing surprising needed storing. Expertise works the same way: when the basics are automatic, you look calm doing hard things. Today’s task: redo one routine as if it were your first time. Eleven steps in a cup of tea. Which part of your day would you bring back from autopilot?",story:"This morning I made tea as if it were my first time — kettle, cup, bag, water, timing, milk. Eleven tiny steps. Normally all of it happens while I am thinking about work, and I remember nothing. That, I learned today, is automatic processing: your brain’s power-saving mode. Conscious control is slow and expensive, so the brain spends it only where something is new or surprising. It is a kind explanation for feeling scattered on busy days: the battery is not broken, it is being spent. Which part of your day would you like to bring back from autopilot?"}}},{id:"psy-d03",month:1,week:1,day:3,dayIndex:3,type:"interactive",title:"How You See What You See",duration:"7 min",summary:"Your eyes are cameras, but your brain is the editor. Perception is construction — and it sometimes overwrites reality.",concepts:["Perception","Top-down processing","Visual illusions"],tryOn:'Find one optical illusion today (search "optical illusion"). Stare at it for 30 seconds and try to make your brain un-see the trick. It will refuse — that refusal is your evidence. Note one line: "My brain edited ___."',cards:[{kind:"hook",body:"You do not see the world. You see the story your brain builds about the world."},{kind:"text",title:"Perception is construction",body:'Light hits your eyes, but "seeing" happens in the brain. Your brain fills gaps, corrects colours, and guesses shapes using what it expects. This is called top-down processing: your knowledge shapes what you perceive. It is usually helpful — and sometimes it edits reality without telling you.'},{kind:"definition",title:"Top-down processing",body:"When your brain uses expectations and past experience to fill in what the senses leave out."},{kind:"example",title:"Everyday example",body:'Read this: "Y0U C4N R34D TH1S." Your eyes saw a mess of numbers, but your brain predicted the words. It does the same with half-heard speech, blurry faces, and messy handwriting. Usually helpful. Occasionally wrong.'},{kind:"practice",title:"Practice task",body:'Find one photo with an optical illusion today (search "optical illusion" and pick one). Watch your brain refuse to believe the measurement. That refusal is top-down processing in action.'}],questions:[{kind:"mcq",question:'Where does "seeing" actually happen?',options:["In the eyes","In the brain","In the light","In the object being looked at"],answer:1,explanation:"Eyes collect light; the brain interprets it. Perception is an act of construction.",concept:"Perception"},{kind:"truefalse",question:"Top-down processing means using expectations to fill in missing information.",options:["True","False"],answer:0,explanation:"Exactly: knowledge from above (the brain) shapes what the senses deliver.",concept:"Top-down processing"},{kind:"mcq",question:'Reading "Y0U C4N R34D TH1S" is mainly an example of…',options:["Eyes adapting to the dark","Top-down processing filling in messy input","A photographic memory","Optical damage to the eye"],answer:1,explanation:"Your expectations of English words overrode the messy pixels. Your brain edited the scene.",concept:"Top-down processing"}],share:{hook:"You do not see the world. You see your brain’s best guess of the world.",concept:"Top-down processing",definition:"When your brain uses expectations to fill in what the senses leave out.",posts:{reflective:'Day 3 of Uneek Academy’s psychology course. Eyes are cameras; the brain is the editor. Perception is construction — your brain fills gaps, predicts words, and fixes colours using what it expects. The technical name is top-down processing. Try reading "Y0U C4N R34D TH1S": your eyes saw noise, your brain produced the sentence. The humbling part: this happens to everything you see, all day, without your permission. Noticing that my own eyes are an editorial process, not a recording, has already made me slower to say "I know what I saw." What has your brain edited for you lately?',direct:'You do not see the world. You see your brain’s best guess. Day 3 of Uneek Academy’s psychology course covers top-down processing: the brain uses expectations to fill in missing information. Cameras capture; brains edit. Proof: "Y0U C4N R34D TH1S." The pixels were noise, but your expectations built the sentence. This is why two people can watch the same argument and describe different events — perception is construction. Practical takeaway: "I know what I saw" is a weaker claim than it feels. What has your brain edited for you this week?',story:'My cousin and I watched the same argument at a family gathering. She described an aggressive shout; I described someone overwhelmed. Both of us were certain. Today’s lesson explains why: perception is construction. The brain edits raw input using expectations — top-down processing. It is why "Y0U C4N R34D TH1S" reads as English and why eyewitnesses disagree. The exercise was an optical illusion that refused to behave even after I measured it. My takeaway: certainty about what I saw is a feeling, not a fact. What has your brain edited for you lately?'}}},{id:"psy-d04",month:1,week:1,day:4,dayIndex:4,type:"reading",title:"The Spotlight of Attention",duration:"6 min",summary:"Attention is a spotlight, not a floodlight. What it misses is as important as what it catches — and that explains the invisible gorilla.",concepts:["Selective attention","Inattentional blindness","Attention as a resource"],tryOn:"Give one conversation 60 full seconds of attention today — no phone, no rehearsing your reply. Timid version: do this on a call where you never speak. Note one detail you would normally have missed.",cards:[{kind:"hook",body:"Attention is a spotlight. Whatever stands outside the beam might as well not exist."},{kind:"text",title:"A spotlight, not a floodlight",body:"Your senses take in far more than you can process. Attention chooses. Focus hard on one thing and other things — even obvious ones — can pass unnoticed. This is not a character flaw; it is a budget. Attention is a limited resource, spent wherever your goals point it."},{kind:"definition",title:"Inattentional blindness",body:"Failing to notice something visible because attention is busy elsewhere."},{kind:"example",title:"Everyday example",body:'In the famous "invisible gorilla" study, people counting basketball passes missed a person in a gorilla suit walking through the scene. Daily version: you cannot hear your name at a loud party until someone says it — then it is suddenly everywhere. The information was always there; the spotlight was elsewhere.'},{kind:"practice",title:"Practice task",body:"In one conversation today, give full attention for 60 seconds — no phone, no planning your reply. Notice how much more you catch. Then notice how quickly the spotlight drifts."}],questions:[{kind:"mcq",question:'The "spotlight" metaphor for attention means that…',options:["We notice everything within a wide area","We process well what we focus on and miss much of the rest","Attention works better at night","Attention cannot be controlled"],answer:1,explanation:"Attention selects a narrow beam. Outside the beam, awareness is thin.",concept:"Selective attention"},{kind:"truefalse",question:'In the "invisible gorilla" study, most people in the gorilla study saw the gorilla because it was so obvious.',options:["True","False"],answer:1,explanation:"About half of viewers miss the gorilla entirely. Busy attention makes visible things invisible.",concept:"Inattentional blindness"},{kind:"scenario",question:"You are rehearsing your presentation while a colleague explains a problem, and you catch none of it. What happened?",options:["They must have mumbled","Your attention spotlight was on your rehearsal, so their words were outside the beam","Your hearing briefly failed","They were not worth listening to"],answer:1,explanation:"Attention is a budget pointed by your goals. Rehearsal spent it all; listening got what was left.",concept:"Attention as a resource"}],share:{hook:"Attention is a spotlight, not a floodlight.",question:"What is standing outside your spotlight right now?",posts:{reflective:"Day 4 of Uneek Academy’s psychology course: attention is a spotlight, not a floodlight. Whatever falls outside the beam might as well not exist — that is why people counting basketball passes miss a gorilla walking through the scene. Attention is not a moral quality; it is a budget, pointed wherever your goals send it. I tried the task: sixty seconds of full attention in one conversation, no phone, no rehearsing my reply. The difference in what I heard was embarrassing and instructive. The question I am carrying: what is standing outside my spotlight right now that someone wishes I could see?",direct:"Attention is a spotlight, not a floodlight. Day 4 of Uneek Academy’s psychology course. If you have not seen the invisible gorilla study, look it up: people counting passes miss a person in a gorilla suit. Attention is a limited budget, pointed by your goals — when you rehearse your reply, you literally cannot take in what is being said. Not a character flaw. A design feature. The fix is cheap: sixty seconds of full attention per conversation. Try it once today and notice how much you have been missing. What is standing outside your spotlight right now?",story:"My teammate asked what she should do about a client problem, and I caught exactly zero of it. Why? I was rehearsing my own presentation in my head. Today’s lesson names it: attention is a spotlight, and mine was pointing at me. The invisible gorilla study shows the same thing on video — focused counters miss a gorilla. Attention is a budget, not a virtue. Tonight I redid one conversation with sixty seconds of true focus. I heard a detail that changed my advice completely. What is standing outside your spotlight right now that someone wishes you could see?"}}},{id:"psy-d05",month:1,week:1,day:5,dayIndex:5,type:"reading",title:"Why Your Brain Takes Shortcuts",duration:"7 min",summary:'Mental shortcuts are fast and usually right. "Usually" is the word that makes psychology necessary.',concepts:["Heuristics","Judgement under uncertainty","When shortcuts fail"],tryOn:"Catch one shortcut. Write two lines: the quick judgement, then the actual evidence. Quiet version: practise on strangers in a queue — zero risk, same muscle.",exercise:"Catch one shortcut today: find a quick judgement you made (someone’s outfit, a headline, a tone of voice) and ask what evidence you actually had.",cards:[{kind:"hook",body:"Your brain is a shortcut machine — fast, efficient, and occasionally confidently wrong."},{kind:"text",title:"Shortcuts by design",body:'The world gives you too much information and too little time. So the brain uses heuristics: mental shortcuts that produce a good-enough answer quickly. They work surprisingly often. But "surprisingly often" is not "always," and the failures are predictable.'},{kind:"definition",title:"Heuristic",body:"A mental shortcut that trades perfect accuracy for speed."},{kind:"example",title:"Everyday example",body:'You hear one loud laugh in a quiet library and instantly judge "rude person." The shortcut: loudness → character. The reality might be someone reading a funny message from a friend. Fast verdict, thin evidence.'},{kind:"practice",title:"Practice task",body:"Use today’s exercise prompt: catch one shortcut, write the judgement, then list the actual evidence. Two lines each. The goal is not to stop judging — it is to see the machinery."}],questions:[{kind:"mcq",question:"Heuristics are best described as…",options:["Mental shortcuts for fast, good-enough judgement","Logical rules that guarantee the right answer","Errors in memory","Emotional reactions"],answer:0,explanation:"Heuristics trade a little accuracy for a lot of speed. Mostly helpful, sometimes misleading.",concept:"Heuristics"},{kind:"truefalse",question:"Mental shortcuts fail in random, unpredictable ways.",options:["True","False"],answer:1,explanation:"Shortcut failures are patterned — which is exactly why a course like this can teach them.",concept:"When shortcuts fail"},{kind:"scenario",question:'A candidate’s handshake is weak, and you instantly think "not confident." What is the shortcut doing?',options:["Reading their personality accurately from one cue","Using one thin signal to stand in for a complex judgement","Applying a legal hiring rule","Nothing — this is careful reasoning"],answer:1,explanation:"One cue standing in for a big conclusion is classic heuristic thinking. Fast, and risky.",concept:"Judgement under uncertainty"}],share:{hook:"Your brain is a shortcut machine — fast, efficient, and occasionally confidently wrong.",question:"What is one quick judgement you made today on thin evidence?",posts:{reflective:'Day 5 of Uneek Academy’s psychology course covered heuristics — the brain’s mental shortcuts. They are not bugs. The world gives too much data and too little time, so the brain trades perfect accuracy for speed. A loud laugh in a library → "rude person." A weak handshake → "not confident." Fast verdicts, thin evidence. The task was to catch one shortcut and list the real evidence behind it. I found three judgements before lunch. The point is not to stop judging — it is to see the machinery running. What is one quick judgement you made today on thin evidence?',direct:'Your brain is a shortcut machine. Day 5 of Uneek Academy’s psychology course: heuristics — mental shortcuts that trade accuracy for speed. They work most of the time, which is why they hide. Loud laugh in a library → "rude person." Weak handshake → "not confident." One thin cue standing in for a whole human being. The exercise: catch a shortcut and list the actual evidence. I found three before lunch. Seeing the machinery is the first step to better judgement. What quick judgement did you make today on thin evidence?',story:"A man laughed loudly in a quiet caf\xe9 and I decided, instantly, that he was rude. Then he turned his laptop and I saw a video call with a toddler dancing on a table. My shortcut — loudness equals character — had delivered a confident, wrong verdict. That is heuristics: the brain’s shortcut system, covered in Day 5 of Uneek Academy’s psychology course. They are needed (too much data, too little time) and they fail in patterned ways. My task: catch one shortcut a day and check the evidence. What quick judgement did you make today on thin evidence?"}}},{id:"psy-d06",month:1,week:1,day:6,dayIndex:6,type:"review",title:"Week 1 Review: The Mind’s First Map",duration:"10 min",summary:"Five ideas, one week: what psychology is, automatic processing, perception, attention, and mental shortcuts.",concepts:["Week 1 synthesis"],tryOn:"Retell this week's five ideas to someone in under two minutes — or to an empty room. The one you stumble on is the one to review.",reviewTopics:["What psychology is","Automatic processing","Top-down processing","Selective attention","Heuristics"],cards:[{kind:"hook",body:"One week in, you already have a working map of the mind’s first machinery."},{kind:"list",title:"This week’s five concepts",items:["What psychology is — careful study of thoughts, feelings, behaviour, and why.","Automatic processing — practised actions run quietly so attention is free.","Top-down processing — expectations fill in what the senses leave out.","Selective attention — the spotlight catches little outside the beam.","Heuristics — fast shortcuts, patterned failures."]},{kind:"text",title:"How they fit together",body:"Perception builds your world, attention chooses what matters, and shortcuts decide fast. Automatic processing keeps it all affordable. Psychology is simply the practice of watching these systems instead of being run by them."},{kind:"practice",title:"Before the quiz",body:"Say the five concepts out loud without looking. Anything you cannot recall goes on your weak list — the quiz will find it anyway."}],questions:[{kind:"mcq",question:"Psychology is best defined as…",options:["The study of how people think, feel, and behave","The practice of reading people’s minds","Advice for living well","The study of brain chemicals only"],answer:0,explanation:"The careful study of thoughts, feelings, behaviour — and why.",concept:"What psychology is"},{kind:"mcq",question:"Why does the brain use automatic processing?",options:["To save effort for new or hard problems","Because it is lazy","To slow everything down","Because conscious thought is impossible"],answer:0,explanation:"Practised actions run quietly; conscious effort is spent carefully.",concept:"Automatic processing"},{kind:"mcq",question:'Reading messy text like "Y0U C4N R34D TH1S" is an example of…',options:["Top-down processing","Inattentional blindness","A heuristic","Autopilot"],answer:0,explanation:"Expectations of language fill in the messy input.",concept:"Top-down processing"},{kind:"mcq",question:"In the invisible gorilla study, people miss the gorilla because…",options:["It was too fast to see","Their attention was busy counting passes","It was hidden behind the players","Their eyes were closed"],answer:1,explanation:"Busy attention makes visible things effectively invisible.",concept:"Selective attention"},{kind:"mcq",question:"A heuristic is…",options:["A mental shortcut trading accuracy for speed","A memory error","A rule that guarantees correctness","A type of emotion"],answer:0,explanation:"Good-enough answers, fast — with patterned failure modes.",concept:"Heuristics"},{kind:"truefalse",question:"Perception is closer to construction than to recording.",options:["True","False"],answer:0,explanation:"The brain builds what you see from input plus expectations.",concept:"Top-down processing"},{kind:"truefalse",question:"Attention is unlimited if you try hard enough.",options:["True","False"],answer:1,explanation:"Attention is a budget; effort points it, it does not enlarge it.",concept:"Selective attention"},{kind:"scenario",question:"You judge someone as unfriendly from a single short text. Which concept best explains this?",options:["Heuristics — a fast shortcut from thin evidence","Top-down processing","Automatic processing","Inattentional blindness"],answer:0,explanation:"One thin cue standing in for a whole person is classic heuristic thinking.",concept:"Heuristics"}],share:{hook:"You do not see the world. You see your brain’s best guess.",question:"Which of the week’s five ideas will you watch for this weekend?",posts:{reflective:"One week of Uneek Academy’s psychology course done. Five ideas: psychology is pattern-noticing, not mind-reading; autopilot saves energy; perception is construction; attention is a spotlight; shortcuts are fast and sometimes wrong. What strikes me is how the pieces fit — the mind spends energy carefully and hands us confident stories about the world. Watching the machinery instead of being run by it is the whole game. The quiz found my weak spot (attention vs. heuristics). Which of these five ideas will you watch for this weekend?",direct:"Week 1 of Uneek Academy’s psychology course complete. The five takeaways: (1) psychology is careful pattern-noticing, (2) the brain runs a power-saving autopilot, (3) perception is construction, (4) attention is a spotlight, (5) heuristics are fast and patterned. That is already enough to change how you listen in meetings and how quickly you judge people. Quiz score is in, weak topics listed. Best question I can ask you: which of these five ideas will you watch for in your own life this weekend?",story:"On Monday I thought psychology was about reading minds. By Saturday I had a map: autopilot runs the basics, the brain edits what I see, attention is a tiny spotlight, and shortcuts make fast judgements on thin evidence. One week of Uneek Academy’s course and I caught myself mid-shortcut twice today — once judging a stranger’s tone, once missing a friend’s point because I was rehearsing mine. The quiz found my weak spot; the weak list will fix it. Which of these five ideas will you watch for this weekend?"}}},{id:"psy-d07",month:1,week:1,day:7,dayIndex:7,type:"rest",title:"Rest Day",duration:"1 min",summary:"Rest is part of the program, not a break from it.",concepts:[],cards:[],questions:[],restMessage:"Your brain consolidates learning while it rests. Today: no lesson, no quiz. Step outside, nap, or do nothing on purpose. Tick rest below and your streak stays alive.",share:{hook:"Rest is where learning settles.",posts:{reflective:"",direct:"",story:""}}},{id:"psy-d08",month:1,week:2,day:1,dayIndex:8,type:"reading",title:"Memory Is a Rebuilder, Not a Recorder",duration:"7 min",summary:"Every time you remember something, you rebuild it — and the rebuild is never quite the original.",concepts:["Reconstructive memory","Encoding","Memory as editing"],tryOn:"Write one strong memory from this week in five sentences. Then check one detail against a photo, a message, or another person. Find the seam — that is the point.",cards:[{kind:"hook",body:"Memory is not a filing cabinet. It is a storyteller with a shaky pen."},{kind:"text",title:"Recording vs. rebuilding",body:"We imagine memory as a recording: capture once, play back forever. It is nothing like that. To remember is to rebuild the event from pieces — what was noticed, what mattered, what was said afterwards. Each rebuild can shift the story slightly."},{kind:"definition",title:"Reconstructive memory",body:"Remembering by rebuilding an event from pieces, which can change the memory each time."},{kind:"example",title:"Everyday example",body:"Two siblings describe the same childhood holiday. Both are certain. Both stories disagree — who cried, who said what, whether it rained. Neither is lying. Each memory was rebuilt hundreds of times, borrowing details from photos, retellings, and feelings."},{kind:"practice",title:"Practice task",body:"Write down one strong memory from this week in five sentences. Then compare it with a photo, message, or another person’s version. Look for the seams."}],questions:[{kind:"mcq",question:"Reconstructive memory means that…",options:["Remembering rebuilds events from pieces and can change them","Memories are stored like videos","We can edit memories at will","Memory only works during sleep"],answer:0,explanation:"Each act of remembering is a rebuild — faithful-ish, and editable by retelling.",concept:"Reconstructive memory"},{kind:"truefalse",question:"A very vivid memory must be accurate.",options:["True","False"],answer:1,explanation:"Vividness is a feeling, not a guarantee. Confidence and accuracy come apart often.",concept:"Memory as editing"},{kind:"scenario",question:"Two friends give completely different accounts of the same dinner, both certain. What is the best explanation?",options:["One of them is lying","Both rebuilt the memory from different noticed details and retellings","Memories do not exist","One was not paying attention at all"],answer:1,explanation:"Reconstruction plus different attention produces divergent, sincere accounts.",concept:"Reconstructive memory"}],share:{hook:"Memory is not a filing cabinet. It is a storyteller with a shaky pen.",question:"How many times have you edited a memory by retelling it?",posts:{reflective:"Day 8 of Uneek Academy’s psychology course: memory is reconstructive. Every act of remembering is a rebuild from pieces — noticed details, feelings, later retellings — and the rebuild drifts. Vividness is not accuracy; certainty is not evidence. I wrote one strong memory from this week in five sentences, then checked it against my phone’s photo timeline. Two details were already wrong. It is humbling in the best way: I can trust my memories as stories that shaped me, less as footage to win arguments with. How many times have you edited a memory just by retelling it?",direct:"Memory is reconstructive, not a recording. Day 8 of Uneek Academy’s psychology course. Every time you remember, you rebuild the event from pieces — and the rebuild drifts. That is why two siblings disagree about the same holiday and both are certain. Vividness is not accuracy. The exercise: write one memory in five sentences and check it against evidence. Two of mine were already wrong. Practical rule: treat confident memories as stories, not footage. How many times have you edited a memory by retelling it?",story:"My brother and I argued about who said what at Christmas 2019. Both certain. Both different. Today’s lesson explains it: memory is a rebuild, not a recording — each retelling edits the file. I tested it by writing one memory from this week and comparing it with my camera roll. Two details were wrong already. There is freedom in that: my memories are stories that shaped me, not security footage. I can stop needing them to be perfect. How many times have you edited a memory just by telling it?"}}},{id:"psy-d09",month:1,week:2,day:2,dayIndex:9,type:"video",title:"Why We Forget",duration:"8 min",summary:"Forgetting is not a defect. It is housekeeping — and there are three simple ways it happens.",concepts:["Forgetting curves","Interference","Retrieval failure"],tryOn:"When you forget something today, name the door: decay, interference, or retrieval failure. Keep a 3-line note. No judgement — just labels.",cards:[{kind:"hook",body:"Forgetting is not a flaw in you. It is a feature of the system."},{kind:"text",title:"Three doors to forgetting",body:"Memories fade if unused (decay). New memories push old ones around (interference). And sometimes the memory is in there, but the cue to open it is missing (retrieval failure). You have experienced all three today."},{kind:"definition",title:"Retrieval failure",body:"The memory exists, but you cannot open it without the right cue — the tip-of-the-tongue feeling."},{kind:"example",title:"Everyday example",body:"You cannot recall an actor’s name at dinner (retrieval failure), then someone mentions the movie and it pops out (the cue arrived). Meanwhile, last week’s meeting agenda has faded (decay) and two passwords now fight in your head (interference)."},{kind:"practice",title:"Practice task",body:"When you forget something today, name which door it likely was: decay, interference, or retrieval failure. No judgement — just classification."}],questions:[{kind:"mcq",question:"Retrieval failure means…",options:["The memory is there but the cue to open it is missing","The memory has decayed completely","A new memory overwrote it","You never encoded it"],answer:0,explanation:"Tip-of-the-tongue is retrieval failure: the file exists, the key is missing.",concept:"Retrieval failure"},{kind:"truefalse",question:"Forgetting is always a failure of the memory system.",options:["True","False"],answer:1,explanation:"Forgetting is housekeeping — it clears space and reduces interference.",concept:"Forgetting curves"},{kind:"scenario",question:"You learn French, then Spanish, and start mixing the vocabulary. What is happening?",options:["Decay of the French","Interference — the new learning jostles the old","Retrieval failure","Encoding failure"],answer:1,explanation:"Similar new material competes with old material. Classic interference.",concept:"Interference"}],share:{hook:"Forgetting is not a flaw in you. It is a feature of the system.",question:"Which kind of forgetting has caught you this week?",posts:{reflective:"Day 9 of Uneek Academy’s psychology course: forgetting has three doors — decay (unused memories fade), interference (new learning jostles old), and retrieval failure (the memory is there, the cue is not). Forgetting is housekeeping, not a defect. Today I classified my forgets instead of feeling bad about them: an actor’s name was retrieval failure; my old password was interference. The reframe is kind and useful. If forgetting has structure, remembering can too — cues, spacing, and sleep. Which kind of forgetting has caught you this week?",direct:"Forgetting is a feature, not a failure. Day 9 of Uneek Academy’s psychology course. Three mechanisms: decay (unused memories fade), interference (new learning jostles old), retrieval failure (memory present, cue missing). Tip-of-the-tongue? Retrieval failure. Mixing up French and Spanish? Interference. The exercise: classify your forgets instead of judging them. It takes the shame out and points to the fix — better cues, spacing, sleep. Which kind of forgetting has caught you this week?",story:"I forgot a client’s name mid-intro today. Old me: panic and self-blame. New me (day 9 of a psychology course): that is retrieval failure — the memory is stored, the cue is missing. I asked about the project they mentioned last month and the name arrived instantly. Forgetting, it turns out, has three doors: decay, interference, retrieval failure. It is housekeeping, not a defect. Classifying my forgets is already less stressful than fearing them. Which kind of forgetting has caught you this week?"}}},{id:"psy-d10",month:1,week:2,day:3,dayIndex:10,type:"interactive",title:"How Memories Are Made",duration:"7 min",summary:"Encoding, storage, retrieval — and why attention at the moment of encoding decides most of memory’s fate.",concepts:["Encoding","Storage","Retrieval","Attention at encoding"],tryOn:"Use the name trick on one person today (real or on screen): hear it, say it back once, picture it. Timid version: practise with names on a news show — nobody knows you are practising.",cards:[{kind:"hook",body:'Most "bad memory" is really "no attention at encoding."'},{kind:"text",title:"Three steps",body:"Memory has three steps: encoding (getting the experience in), storage (keeping it), retrieval (getting it out). If encoding was rushed or distracted, storage has little to work with. You cannot retrieve what never got in."},{kind:"definition",title:"Encoding",body:"The first step of memory: turning an experience into something the brain can store."},{kind:"example",title:"Everyday example",body:"Someone introduces themselves while you are checking your phone. Thirty seconds later the name is gone. That is not a bad memory. Nothing was encoded. The phone ate the attention that encoding needed."},{kind:"practice",title:"Practice task",body:'Meet one new name today (or re-learn one you keep forgetting). Hear it, say it back, and connect it to an image ("Grace moves with grace"). Notice the difference.'}],questions:[{kind:"mcq",question:"Which is the correct order?",options:["Encoding → storage → retrieval","Storage → encoding → retrieval","Retrieval → storage → encoding","Encoding → retrieval → storage"],answer:0,explanation:"In, keep, out — in that order.",concept:"Encoding"},{kind:"scenario",question:"You read a full page and cannot recall a single sentence. Where did it most likely fail?",options:["Storage decayed instantly","Encoding — attention was elsewhere while reading","Retrieval only; the page is perfectly stored","The page was too long"],answer:1,explanation:"Reading with a distracted mind is looking without encoding.",concept:"Attention at encoding"},{kind:"truefalse",question:"Connecting a new name to an image helps retrieval later.",options:["True","False"],answer:0,explanation:"Images and associations create extra cues — extra doors into the memory.",concept:"Retrieval"}],share:{hook:'Most "bad memory" is really "no attention at encoding."',question:"What did you fail to encode today — and where was your attention?",posts:{reflective:'Day 10 of Uneek Academy’s psychology course: memory is encoding → storage → retrieval. The quiet insight is that most "bad memory" happens at step one. If attention is elsewhere when the moment arrives, nothing gets in to store. I tested it with names: hear it, say it back, attach an image. "Grace moves with grace" — instant retrieval four hours later. It is a small, practical upgrade that reframes the problem. I do not have a bad memory. I have been absent at the moment of capture. What did you fail to encode today?',direct:'Most "bad memory" is really "no attention at encoding." Day 10 of Uneek Academy’s psychology course. Memory runs encoding → storage → retrieval, and step one is where phones destroy it. If you are checking messages during an introduction, the name never gets in — there is nothing to retrieve. Fix: hear the name, say it back, attach an image. Tested it today; retrieval was instant hours later. Stop buying memory supplements; buy attention. What did you fail to encode today, and where was your attention?',story:'A man told me his name at an event while I glanced at my phone. Gone in seconds. Today’s lesson called my bluff: that was not forgetting, that was never encoding. The fix is embarrassingly simple — hear it, say it back, picture it. This afternoon I tried "Tobi drives a taxi" (a stretch, but it stuck). Memory is a three-step pipeline and my attention is the gate at step one. I do not have a bad memory. I have been missing my own life at the moment of capture. What did you fail to encode today?'}}},{id:"psy-d11",month:1,week:2,day:4,dayIndex:11,type:"reading",title:"Thoughts Are Sentences in Your Head",duration:"6 min",summary:"That running commentary is made of actual sentences — and once you can hear them, you can work with them.",concepts:["Automatic thoughts","Self-talk","Thought awareness"],tryOn:"Catch three sentences in your head today and write them word for word. If that feels too raw, start with sentences about something small — traffic, lunch, the weather.",exercise:"Catch three sentences in your head today and write them down word for word. No editing. The exact wording matters.",cards:[{kind:"hook",body:"You talk to yourself all day. The only question is what you are saying."},{kind:"text",title:"The inner commentary",body:'Underneath the day there is a running stream of short sentences: "I’m late." "She looked annoyed." "I’ll mess this up." These automatic thoughts are fast, specific, and mostly believed without inspection. Psychology’s first trick is simply catching them.'},{kind:"definition",title:"Automatic thought",body:"A quick, spontaneous sentence in the mind that shapes how you feel and act."},{kind:"example",title:"Everyday example",body:'You wave at a friend and they do not wave back. The sentence arrives instantly: "They’re ignoring me." Notice it is a sentence, not a fact. The same scene could read: "They didn’t see me." Same event, different sentence, different feeling.'},{kind:"practice",title:"Practice task",body:"Run today’s exercise: catch three sentences, write them exactly. Do not argue with them yet. Catching comes before changing — always."}],questions:[{kind:"mcq",question:"Automatic thoughts are best described as…",options:["Quick spontaneous sentences that shape feelings and actions","Carefully reasoned conclusions","Things other people say to us","Random words with no effect"],answer:0,explanation:"Fast, specific, and usually believed on arrival. First step: catch them.",concept:"Automatic thoughts"},{kind:"truefalse",question:"You must challenge every negative thought immediately.",options:["True","False"],answer:1,explanation:"Catching comes before changing. Inspection first; argument second.",concept:"Thought awareness"},{kind:"scenario",question:'A friend does not wave back and you think "They’re ignoring me." What is the useful first move?',options:["Decide the friendship is over","Notice the sentence as a sentence — not a fact — and consider other readings","Force yourself to think something positive","Pretend it did not happen"],answer:1,explanation:"One event, many possible sentences. The skill is noticing which one arrived.",concept:"Self-talk"}],share:{hook:"You talk to yourself all day. The only question is what you are saying.",question:"What is one sentence your inner voice repeats?",posts:{reflective:'Day 11 of Uneek Academy’s psychology course: thoughts are actual sentences. Under the day runs a commentary — "I’m late," "they looked annoyed," "I’ll mess this up" — fast, specific, and believed without inspection. The exercise was to catch three of them word for word. Mine were sharper than I expected; one was simply untrue. Noticing is the skill. Not fixing, not arguing — noticing. A friend waved past me and my sentence was "they’re ignoring me"; the truer one was "they didn’t see me." Same event, different sentence, different evening. What is one sentence your inner voice repeats?',direct:'Your thoughts are sentences, and you can audit them. Day 11 of Uneek Academy’s psychology course: automatic thoughts are quick spontaneous sentences that shape feelings and action. The exercise: catch three today and write them word for word. Mine were sharper than expected, and one was plain false. The order matters — catch before you challenge. Same event ("friend didn’t wave back") supports different sentences: "they’re ignoring me" vs "they didn’t see me." Pick your sentence and you pick your evening. What is one sentence your inner voice repeats?',story:'I waved at a friend and she walked past. Instant sentence: "She’s ignoring me." I wrote it down — day 11 of Uneek Academy’s psychology course taught me to catch these — and kept going. Two hours later she texted: she had just left an argument and saw nothing at all. My sentence had been fiction, and I had been feeling hurt by it. Thoughts are real sentences with real power. The exercise is small and strange: catch three, write them exactly. What is one sentence your inner voice repeats?'}}},{id:"psy-d12",month:1,week:2,day:5,dayIndex:12,type:"reading",title:"Emotions vs. Thoughts",duration:"7 min",summary:"Feelings and thoughts are different things — tangled together, but separable. Learning to tell them apart is a superpower.",concepts:["Emotions vs. thoughts","Labelling feelings","The feeling–thought gap"],tryOn:'Next time a strong feeling lands, split the page: "What I feel" (one word) on the left, "What I think" (sentences) on the right. Once, privately — notebook or phone.',exercise:'Next time you feel a strong emotion, split the page in two: "What I feel" (one word) and "What I think" (the sentences). Notice they are different columns.',cards:[{kind:"hook",body:'"I feel like they don’t respect me" is not a feeling. It is a thought wearing a feeling’s clothes.'},{kind:"text",title:"Two different things",body:'Emotions are body-states: anger, sadness, fear, joy — felt, not argued. Thoughts are sentences: "This is unfair." They influence each other constantly, but they are not the same object. Most "feelings" people name are actually thoughts: "I feel ignored," "I feel like a failure."'},{kind:"definition",title:"Emotion",body:"A body-state you feel (anger, fear, joy, sadness) — not a sentence you tell yourself."},{kind:"example",title:"Everyday example",body:'"I feel disrespected" mixes both. The feeling might be anger (hot face, tight jaw). The thought is "They don’t respect me." Split them and you get options: the emotion can be soothed, the thought can be checked.'},{kind:"practice",title:"Practice task",body:"Run today’s exercise when a strong emotion arrives. Two columns: feeling-word on the left, sentences on the right. This one habit is the foundation of everything in Month 5."}],questions:[{kind:"mcq",question:"Which of these is an emotion, strictly speaking?",options:['"I feel like a failure"',"Anger",'"I feel ignored"','"I feel like quitting"'],answer:1,explanation:"Anger is a body-state. The others are thoughts wearing feeling words.",concept:"Emotions vs. thoughts"},{kind:"truefalse",question:'"I feel disrespected" names a pure emotion.',options:["True","False"],answer:1,explanation:'It mixes a feeling (maybe anger) with a thought ("they don’t respect me").',concept:"Emotions vs. thoughts"},{kind:"scenario",question:"Why bother splitting feelings from thoughts?",options:["It is just academic; nothing changes","Each can be worked with differently — feelings soothed, thoughts checked","Feelings are more accurate than thoughts","Thoughts should always be ignored"],answer:1,explanation:"Separating the two gives you two handles instead of one tangled knot.",concept:"The feeling–thought gap"}],share:{hook:'"I feel like they don’t respect me" is not a feeling. It is a thought in disguise.',concept:"Emotion",definition:"A body-state you feel — not a sentence you tell yourself.",posts:{reflective:'Day 12 of Uneek Academy’s psychology course untangled something I say constantly. "I feel disrespected" is not a pure emotion. The feeling is anger — hot face, tight jaw. The thought is "they don’t respect me." Two different objects. Feelings are body-states to soothe; thoughts are sentences to check. The exercise: when a strong emotion lands, split the page — "What I feel" (one word) vs "What I think" (the sentences). The columns do not match, and that gap is where choice lives. Which of your "feelings" might actually be thoughts?',direct:'"I feel disrespected" is not a feeling. It is a thought wearing a feeling’s clothes. Day 12 of Uneek Academy’s psychology course separates emotions (body-states: anger, fear, joy) from thoughts (sentences: "they don’t respect me"). The split matters because each has a different fix: feelings are soothed, thoughts are checked. Exercise: when emotion hits, two columns — "what I feel" in one word, "what I think" in sentences. The gap between the columns is where your options live. Which of your "feelings" are actually thoughts?',story:'I told a friend "I feel like my boss doesn’t respect me." Day 12 of the course asked me to split that sentence. Left column, the feeling: anger — jaw tight, face hot. Right column, the thought: "he doesn’t respect me." Two objects, not one. The anger responded to a walk and water. The thought needed evidence — and it turned out weaker than it felt. Feelings are body-states; thoughts are sentences. Mixing them keeps both tangled. Which of your "feelings" might actually be thoughts?'}}},{id:"psy-d13",month:1,week:2,day:6,dayIndex:13,type:"review",title:"Week 2 Review: Memory and Thoughts",duration:"10 min",summary:"Five ideas, one week: reconstructive memory, forgetting, encoding, automatic thoughts, and the feelings–thoughts split.",concepts:["Week 2 synthesis"],tryOn:'Explain the feelings-vs-thoughts split to one person this week using your own example. Script: "I used to say I felt disrespected — that was a thought; the feeling was anger."',reviewTopics:["Reconstructive memory","Retrieval failure","Encoding","Automatic thoughts","Emotions vs. thoughts"],cards:[{kind:"hook",body:"Memory rebuilds, thoughts narrate, feelings surge. Week 2 taught you to tell the three apart."},{kind:"list",title:"This week’s five concepts",items:["Reconstructive memory — remembering is rebuilding; the story drifts.","Forgetting — decay, interference, retrieval failure. Housekeeping, not failure.","Encoding — get it in with attention or it is not stored.","Automatic thoughts — quick sentences that shape feeling and action.","Emotions vs. thoughts — body-states to soothe, sentences to check."]},{kind:"text",title:"How they fit together",body:"What you encoded becomes memory, rebuilt each time you tell it. Your thoughts narrate the present while feelings surge through the body. Telling the three apart gives you handles on all three."}],questions:[{kind:"mcq",question:"Remembering an event differently each time is called…",options:["Reconstructive memory","Retrieval failure","Interference","Encoding"],answer:0,explanation:"Each remember is a rebuild from pieces — and the pieces shift.",concept:"Reconstructive memory"},{kind:"mcq",question:"Tip-of-the-tongue is…",options:["Retrieval failure","Decay","Interference","Poor encoding"],answer:0,explanation:"The memory is present; the cue is missing.",concept:"Retrieval failure"},{kind:"mcq",question:"You read a page distracted and recall nothing. The failure was at…",options:["Encoding","Storage","Retrieval","Forgetting"],answer:0,explanation:"Attention at encoding decides most of memory’s fate.",concept:"Encoding"},{kind:"mcq",question:"Automatic thoughts are…",options:["Quick spontaneous sentences","Careful conclusions","Other people’s words","Emotions"],answer:0,explanation:"Fast, specific, and believed on arrival — until you catch them.",concept:"Automatic thoughts"},{kind:"mcq",question:"Which is an emotion rather than a thought?",options:["Fear",'"I feel ignored"','"I feel like a failure"','"I feel like quitting"'],answer:0,explanation:"Fear is a body-state. The rest are sentences using feeling words.",concept:"Emotions vs. thoughts"},{kind:"truefalse",question:"Forgetting is always a personal failure.",options:["True","False"],answer:1,explanation:"Forgetting is housekeeping — decay, interference, retrieval failure.",concept:"Retrieval failure"},{kind:"truefalse",question:"Vividness of a memory guarantees its accuracy.",options:["True","False"],answer:1,explanation:"Confidence and accuracy come apart. Vividness is a feeling.",concept:"Reconstructive memory"},{kind:"scenario",question:'You feel "like everyone noticed my mistake." Using today’s tools, the first move is…',options:['Split the feeling (embarrassment?) from the thought ("everyone noticed") and check the thought',"Push the feeling away","Agree with the thought and apologise to everyone","Assume the thought is true and avoid the meeting"],answer:0,explanation:"Feelings and thoughts get different treatments. Split first.",concept:"Emotions vs. thoughts"}],share:{hook:"Memory rebuilds, thoughts narrate, feelings surge.",question:"Which of the week’s ideas showed up in your own life?",posts:{reflective:'Two weeks of Uneek Academy’s psychology course. This week: memory is a rebuild, forgetting is housekeeping, encoding demands attention, thoughts are sentences, and feelings are body-states — not the same thing. The feelings–thoughts split alone is worth the time; "I feel disrespected" suddenly has two parts, and two parts means two handles. I am catching sentences mid-air now and checking memories before I use them as evidence. Slowly, the machinery becomes visible. Which of this week’s ideas showed up in your own life?',direct:'Week 2 of Uneek Academy’s psychology course done. Five tools: reconstructive memory, three doors of forgetting, encoding with attention, catching automatic thoughts, splitting feelings from thoughts. The split is the one to steal: "I feel disrespected" = feeling (anger) + thought ("they don’t respect me"). Feelings get soothed; thoughts get checked. That is a real upgrade in how you handle hard conversations. Which of these five ideas showed up in your life this week?',story:'Tonight I caught myself mid-sentence — "I feel like no one values my work" — and, courtesy of week 2 of Uneek Academy’s psychology course, split it. Feeling: sadness. Thought: "no one values my work." The sadness needed a walk. The thought needed evidence, and evidence was thin. Two weeks in, the theme is clear: memory is a rebuild, thoughts are sentences, feelings are weather. You can work with each — once you can tell them apart. Which of this week’s ideas showed up in your life?'}}},{id:"psy-d14",month:1,week:2,day:7,dayIndex:14,type:"rest",title:"Rest Day",duration:"1 min",summary:"Rest is part of the program, not a break from it.",concepts:[],cards:[],questions:[],restMessage:"Two weeks done. Today the only task is to rest on purpose — walk, nap, or stare at the ceiling. Memories consolidate in rest. Tick the box and keep the streak.",share:{hook:"Rest is where learning settles.",posts:{reflective:"",direct:"",story:""}}},{id:"psy-d15",month:1,week:3,day:1,dayIndex:15,type:"reading",title:"Where Thoughts Come From",duration:"7 min",summary:"Thoughts feel automatic because they are — they grow from beliefs planted long before you noticed them.",concepts:["Beliefs","Thought origins","Core beliefs"],tryOn:'Take one caught thought and ask: "What would have to be true about the world for this to make sense?" Write the answer. That answer is a belief — you just named a root.',cards:[{kind:"hook",body:"Thoughts are the leaves. Beliefs are the roots. You have been staring at the leaves."},{kind:"text",title:"The layer under the sentence",body:'Automatic thoughts sit on top of beliefs — broad, deep conclusions about yourself, others, and the world ("I must be useful to be loved"). Beliefs form slowly through experience, family, culture, and repetition. Thoughts are what they say in daily conversation.'},{kind:"definition",title:"Core belief",body:"A deep, long-held conclusion about yourself, others, or the world that shapes daily thoughts."},{kind:"example",title:"Everyday example",body:'A small critique at work triggers "I’m useless." The sentence is a leaf. The root may be a belief formed years ago: "If I’m not perfect, I’m rejected." Change gets easier when you find the root instead of pruning leaves forever.'},{kind:"practice",title:"Practice task",body:'Take one sentence you caught this week ("I’ll mess this up") and ask: "What would have to be true about the world for this sentence to make sense?" Write the answer. That is usually a belief.'}],questions:[{kind:"mcq",question:"The relationship between beliefs and automatic thoughts is…",options:["Beliefs are deep roots; thoughts are the daily leaves","They are the same thing","Thoughts come first, beliefs form from them only","Beliefs are conscious choices"],answer:0,explanation:"Daily sentences grow out of long-held conclusions.",concept:"Beliefs"},{kind:"truefalse",question:"Core beliefs form overnight from a single event.",options:["True","False"],answer:1,explanation:"They build slowly through repeated experience, culture, and family.",concept:"Core beliefs"},{kind:"scenario",question:'A minor critique triggers "I’m useless." What is the deeper layer worth exploring?',options:["A core belief about needing to be perfect to be accepted","The wording of the critique","Your blood sugar","The time of day"],answer:0,explanation:"The daily sentence usually broadcasts a deeper conclusion.",concept:"Thought origins"}],share:{hook:"Thoughts are the leaves. Beliefs are the roots.",question:"What belief might be growing under one of your automatic thoughts?",posts:{reflective:'Day 15 of Uneek Academy’s psychology course: thoughts are the leaves, beliefs are the roots. Automatic sentences — "I’ll mess this up" — sit on top of deep conclusions formed over years ("if I’m not perfect, I’m rejected"). The exercise: take one caught thought and ask what would have to be true about the world for it to make sense. My answer was uncomfortable and clarifying. You cannot prune leaves forever; at some point you look at the roots. What belief might be growing under one of your automatic thoughts?',direct:'Thoughts are the leaves; beliefs are the roots. Day 15 of Uneek Academy’s psychology course. Automatic thoughts ("I’m useless") broadcast core beliefs formed long ago ("I must be perfect to be accepted"). The exercise: for one thought, ask "what would have to be true about the world for this to make sense?" The answer is your belief. Stop pruning leaves; find the root. What belief might be growing under one of your automatic thoughts?',story:'A one-line critique at work sent me spiralling into "I’m useless." Day 15 of the course asked the key question: what would have to be true for that sentence to make sense? My answer: "If I’m not perfect, I’m out." That is not today’s thought — that is an old root, probably watered for years. Thoughts are the leaves; beliefs are the roots. I am done pruning. What belief might be growing under one of your automatic thoughts?'}}},{id:"psy-d16",month:1,week:3,day:2,dayIndex:16,type:"video",title:"The Story Your Brain Tells",duration:"8 min",summary:"The brain is a story machine. It fills gaps with plots — and the plot is usually about you.",concepts:["Narrative brain","Confabulation","Story vs. evidence"],tryOn:'Label one story today: "My story is…" then write one boring alternative. Timid version: practise on fiction — explain why a TV character did something, then invent a duller reason.',cards:[{kind:"hook",body:"When information runs out, the brain does not stay quiet. It writes fiction."},{kind:"text",title:"A machine that needs a plot",body:"The brain hates loose ends. Given partial information, it generates a story that connects the dots — with you as the main character. This is why ambiguity feels so uncomfortable: the story-machine is running without data, and its favourite genre is threat."},{kind:"definition",title:"Confabulation",body:"Filling gaps in memory or information with plausible stories — believed sincerely."},{kind:"example",title:"Everyday example",body:'Your messages are left on read. The story arrives instantly: "They’re upset with me." Zero evidence, full plot, main character: you. The data might be that their phone died. The brain wrote a thriller; reality was a comedy.'},{kind:"practice",title:"Practice task",body:'The next time you invent a story about someone’s behaviour, label it: "My story is…" Then write one boring alternative story. Both are guesses; only one is making you suffer.'}],questions:[{kind:"mcq",question:"When information is missing, the brain tends to…",options:["Fill gaps with a plausible story","Stay carefully silent","Forget the situation entirely","Ask for more data every time"],answer:0,explanation:"The story machine runs on whatever data exists — even none.",concept:"Narrative brain"},{kind:"truefalse",question:"Confabulated stories are told knowingly as fiction.",options:["True","False"],answer:1,explanation:"Confabulation is sincere — the person believes the story they produced.",concept:"Confabulation"},{kind:"scenario",question:'A friend leaves messages on read and you think "They’re angry with me." The best move is…',options:["Label it as your story and write one boring alternative","Assume the story is true and withdraw","Send an angry reply","Ignore your feelings entirely"],answer:0,explanation:"Two competing stories, zero evidence. Name yours first.",concept:"Story vs. evidence"}],share:{hook:"When information runs out, the brain does not stay quiet. It writes fiction.",question:"What story did you write today on almost no data?",posts:{reflective:'Day 16 of Uneek Academy’s psychology course: the brain is a story machine. Left on read? It writes "they’re angry with me" instantly, casting you as the main character. The technical word is confabulation — filling gaps with plausible fiction, sincerely believed. The task today: label one of your stories "my story is…" and write a boring alternative. Mine (a colleague’s short reply) had two versions: "she thinks I’m incompetent" vs "she was in a meeting." The boredom of the second one is the point. What story did you write today on almost no data?',direct:'Your brain writes fiction all day. Day 16 of Uneek Academy’s psychology course: when data runs out, the story machine fills gaps — usually with you as the main character. Messages on read → "they’re angry with me." A short reply → "I’m incompetent." Confabulation: plausible stories, sincerely believed. Fix: label it "my story is…" and write one boring alternative. Reality is usually boring. What story did you write today on almost no data?',story:'A colleague replied "ok" to my proposal and my brain produced an entire drama: she hates it, I look foolish, the project is dead. Then day 16 of the course told me to write "my story is…" at the top of the page. My story was fiction on two data points. The boring alternative: she was walking into a meeting. Later she replied with praise. The brain is a story machine that hates loose ends; my job is to notice the genre. What story did you write today on almost no data?'}}},{id:"psy-d17",month:1,week:3,day:3,dayIndex:17,type:"interactive",title:"Feelings First, Reasons Later",duration:"7 min",summary:"We often feel a conclusion before we reason it — then build the reasoning as a press release.",concepts:["Emotion-first judgement","Post-hoc reasoning","Deliberation"],tryOn:"On one small decision today, write your gut verdict first, your reasons second. Then ask: could the opposite verdict hire reasons just as easily?",cards:[{kind:"hook",body:"The verdict often arrives before the evidence. The evidence is hired afterwards."},{kind:"text",title:"The press-release brain",body:"Research on moral and emotional judgement suggests feelings often come first; reasoning follows to explain them. Reasoning is not useless — it can revise the verdict — but it must know it works for the feeling, not the other way around."},{kind:"definition",title:"Post-hoc reasoning",body:"Building an explanation after the conclusion has already been reached."},{kind:"example",title:"Everyday example",body:'You dislike a proposal the second you hear it, then spend ten minutes producing "rational" objections. Ask: did the reasons cause the dislike, or did the dislike hire the reasons? Swap positions with a friend and watch the reasons rearrange instantly.'},{kind:"practice",title:"Practice task",body:"In one decision today, write your gut verdict first (one line), then your reasons. Ask honestly: if the verdict were opposite, could I write reasons just as easily?"}],questions:[{kind:"mcq",question:"Post-hoc reasoning means…",options:["Explaining a conclusion that was already reached emotionally","Reasoning before deciding","Forgetting your reasons","Reasoning during sleep"],answer:0,explanation:"The press release after the decision — not the cause of it.",concept:"Post-hoc reasoning"},{kind:"truefalse",question:"Emotions and reasoning always arrive in the same order.",options:["True","False"],answer:1,explanation:"Often feeling leads and reasoning follows. Not always — but often.",concept:"Emotion-first judgement"},{kind:"scenario",question:"You instantly dislike an idea and list three objections after. The honest question is…",options:["Did my dislike hire these reasons?","Are three objections enough?","Who else dislikes it?","Should I say nothing?"],answer:0,explanation:"Test whether the reasons caused the verdict or the verdict hired the reasons.",concept:"Deliberation"}],share:{hook:"The verdict often arrives before the evidence.",question:"What verdict did you reach first and justify later — today?",posts:{reflective:"Day 17 of Uneek Academy’s psychology course: feelings often deliver the verdict first; reasoning arrives later as a press release. Not a comfortable idea for someone who prides themselves on logic. The exercise: write your gut verdict before your reasons, then ask if the opposite verdict could hire reasons just as easily. Mine could. Deliberation still matters — it can revise the verdict — but only if it knows who it works for. What verdict did you reach first and justify later today?",direct:"Your reasoning may be a press release. Day 17 of Uneek Academy’s psychology course: emotion often judges first; reasons are hired afterwards to explain it. Test it: write the gut verdict before the reasons, then ask if the opposite verdict could justify itself just as well. Mine could. The fix is not to kill feelings — it is to stop confusing hired reasons for honest ones. What verdict did you reach first and justify later today?",story:'I rejected an idea in a meeting within two seconds and spent ten minutes producing elegant objections. Then I did day 17’s exercise: gut verdict first, reasons second, and one question — could the opposite hire reasons just as easily? Easily, yes. My logic had been a press release for my feelings. The lesson is not "feelings bad" — feelings carry information. It is "know who your reasoning works for." What verdict did you reach first and justify later today?'}}},{id:"psy-d18",month:1,week:3,day:4,dayIndex:18,type:"reading",title:"Naming Emotions Accurately",duration:"6 min",summary:"The more precisely you can name a feeling, the less power it has. This skill has a name: emotional granularity.",concepts:["Emotional granularity","Labelling","Precision of feeling"],tryOn:'Upgrade three vague feelings today ("bad" → disappointed / anxious / embarrassed / tired). Keep a 10-word feelings list in your notes app and use it once before bed.',exercise:'Upgrade three vague feelings today. "Bad" → is it disappointed, anxious, embarrassed, tired? Use a feelings list if you get stuck.',cards:[{kind:"hook",body:"Name it to tame it — but only if you name it precisely."},{kind:"text",title:"Granularity is a skill",body:"Some people use three feeling-words for everything: fine, bad, good. Others distinguish disappointed from frustrated, anxious from excited. That precision is emotional granularity, and it predicts better regulation: a specific feeling suggests a specific action."},{kind:"definition",title:"Emotional granularity",body:'How precisely you can name what you feel — the difference between "bad" and "disappointed".'},{kind:"example",title:"Everyday example",body:'"I feel bad" offers no direction. "I’m disappointed the plan fell through" points at the loss and suggests what helps: replanning. "I’m anxious about the review" points at uncertainty and suggests preparation or reassurance. Precise names, precise next steps.'},{kind:"practice",title:"Practice task",body:"Run today’s exercise: upgrade three vague feelings. Keep a short feelings list in your notes app — ten words beat three."}],questions:[{kind:"mcq",question:"Emotional granularity is…",options:["Precision in naming what you feel","Feeling more strongly than others","Hiding feelings well","A personality type"],answer:0,explanation:"Specific names for specific states — a learnable skill.",concept:"Emotional granularity"},{kind:"truefalse",question:"A precise feeling-word suggests a more precise response.",options:["True","False"],answer:0,explanation:"Disappointment points to loss; anxiety points to uncertainty. Different fixes.",concept:"Labelling"},{kind:"scenario",question:"Which is the most granular description?",options:['"I feel bad"','"I’m a bit off"','"I’m frustrated that the deadline moved without asking me"','"I’m fine"'],answer:2,explanation:"Specific state + specific cause + specific context. That is granularity.",concept:"Precision of feeling"}],share:{hook:"Name it to tame it — but only if you name it precisely.",concept:"Emotional granularity",definition:"How precisely you can name what you feel.",posts:{reflective:'Day 18 of Uneek Academy’s psychology course introduced emotional granularity: how precisely you can name what you feel. Three words — fine, bad, good — leave you with no direction. "Disappointed the plan fell through" suggests replanning; "anxious about the review" suggests preparing. Precise names give precise next steps. I upgraded three vague feelings today and one of them changed from "bad" to "overlooked" — which quietly suggested asking for what I needed instead of sulking. Name it to tame it. What is one feeling you could rename this week?',direct:'Stop saying "I feel bad." Day 18 of Uneek Academy’s psychology course: emotional granularity — precision in naming feelings — predicts better regulation. "Disappointed" points to loss and suggests replanning. "Anxious" points to uncertainty and suggests preparation. Vague words give vague lives. The exercise: upgrade three vague feelings today using a feelings list. One of mine went from "bad" to "overlooked" and instantly suggested an action. What is one feeling you could rename this week?',story:'I said "I just feel bad" and my friend asked "bad like sad, bad like angry, bad like tired?" Three questions later I had it: overlooked. The whole situation looked different. That is emotional granularity, from day 18 of Uneek Academy’s psychology course: precise names for feelings suggest precise next steps. "Overlooked" meant I needed to ask for something, not sulk. I now keep a ten-word feelings list on my phone. What is one feeling you could rename this week?'}}},{id:"psy-d19",month:1,week:3,day:5,dayIndex:19,type:"reading",title:"The Thought–Feeling–Action Loop",duration:"7 min",summary:"Thoughts, feelings, and actions run in a loop. Find the loop and you find three places to intervene.",concepts:["The loop model","Intervention points","Behavioural change"],tryOn:"Map one recent mood dip in three boxes: the thought, the feeling, the action. Circle the easiest door — usually the action — and try a 5-minute version of it this week.",exercise:"Map one recent mood dip: the thought, the feeling, and the action. Mark which point in the loop is easiest for you to change first.",cards:[{kind:"hook",body:"Thoughts spark feelings. Feelings drive actions. Actions feed thoughts. The loop runs all day."},{kind:"text",title:"One model, three handles",body:'The thought–feeling–action loop is a simple map: a thought ("I’ll fail") sparks a feeling (anxiety), which drives an action (avoidance), which confirms the thought ("See? I can’t"). Loops can spiral down or up. The value of the map is intervention: you can enter at any of the three points.'},{kind:"definition",title:"Thought–feeling–action loop",body:"The cycle where thoughts spark feelings, feelings drive actions, and actions feed back into thoughts."},{kind:"example",title:"Everyday example",body:'Thought: "They don’t want me there." Feeling: hurt. Action: skip the gathering. Thought grows: "See, I’m excluded." Enter anywhere: check the thought ("Did anyone say that?"), soothe the feeling (call a friend), or change the action (go for one hour).'},{kind:"practice",title:"Practice task",body:"Run today’s exercise on one mood dip. Draw the three boxes and arrows. Changing just the action box is often the fastest way to break a loop."}],questions:[{kind:"mcq",question:"The loop model says that thoughts, feelings, and actions…",options:["Influence each other in a cycle","Happen only in order and never repeat","Are unrelated","Only matter in therapy"],answer:0,explanation:"Each drives the next — and the last feeds the first.",concept:"The loop model"},{kind:"scenario",question:'Thought: "I’ll fail." Feeling: anxious. Action: avoid. What is the loop reinforcing?',options:["The belief that you cannot do it","Your preparation skills","Nothing","Your memory"],answer:0,explanation:"Avoidance feels like proof the task was impossible. The loop closes.",concept:"Intervention points"},{kind:"mcq",question:"Where can you intervene in the loop?",options:["At any point: thought, feeling, or action","Only at thoughts","Only at feelings","Nowhere once it starts"],answer:0,explanation:"Three handles. Action is often the fastest entry point.",concept:"Behavioural change"}],share:{hook:"Thoughts spark feelings. Feelings drive actions. Actions feed thoughts.",question:"Where in the loop do you usually get stuck?",posts:{reflective:'Day 19 of Uneek Academy’s psychology course connected the week: the thought–feeling–action loop. "I’ll fail" (thought) → anxiety (feeling) → avoidance (action) → "see, I can’t" (thought). Loops can spiral down or up, and — the hopeful part — you can enter at any of the three points. I mapped one mood dip from Tuesday and found the action box was the easiest door: a five-minute start broke a loop that had been running for days. Where in the loop do you usually get stuck?',direct:'One model, three handles: the thought–feeling–action loop. Day 19 of Uneek Academy’s psychology course. Thoughts spark feelings, feelings drive actions, actions feed thoughts — "I’ll fail" → anxiety → avoidance → "see, I can’t." Break the cycle at any point. The fastest door is usually action: five minutes of starting beats an hour of spiralling. Map one mood dip today and mark your easiest entry point. Where in the loop do you usually get stuck?',story:'Tuesday’s mood dip had a shape: "they think I’m unqualified" → shame → hiding in my inbox → feeling more invisible. Day 19 of the course gave me the map — thoughts, feelings, actions in a loop — and one instruction: enter anywhere. I chose action: ten minutes of the task I was avoiding. The feeling softened before the thought changed. Three boxes and arrows, and suddenly the spiral has doors. Where in the loop do you usually get stuck?'}}},{id:"psy-d20",month:1,week:3,day:6,dayIndex:20,type:"review",title:"Week 3 Review: The Roots of Thought",duration:"10 min",summary:"Five ideas: beliefs under thoughts, the story machine, feelings-first judgements, emotional granularity, and the loop.",concepts:["Week 3 synthesis"],tryOn:'Teach the loop model to someone — or voice-note it to yourself: "thoughts spark feelings, feelings drive actions, actions feed thoughts." Then notice one loop running in your day.',reviewTopics:["Beliefs vs. thoughts","Narrative brain","Post-hoc reasoning","Emotional granularity","The thought–feeling–action loop"],cards:[{kind:"hook",body:"You can now see the machinery behind a mood: roots, stories, verdicts, names, loops."},{kind:"list",title:"This week’s five concepts",items:["Beliefs vs. thoughts — leaves and roots.","Narrative brain — gaps get fiction, sincerely believed.","Post-hoc reasoning — verdict first, press release second.","Emotional granularity — precise names give precise next steps.","The loop — thoughts, feelings, actions feeding each other."]},{kind:"text",title:"How they fit together",body:"Beliefs generate thoughts; thoughts enter loops with feelings and actions; feelings get named (or not); and the story machine narrates all of it. Week 4 builds the first tools on top of this map."}],questions:[{kind:"mcq",question:'"Thoughts are leaves, beliefs are roots" means…',options:["Daily thoughts grow from deeper long-held conclusions","Beliefs are less important","Thoughts and beliefs are identical","Roots are conscious"],answer:0,explanation:"Change the root and the leaves change.",concept:"Beliefs vs. thoughts"},{kind:"mcq",question:"Filling gaps with plausible, sincere fiction is…",options:["Confabulation","Post-hoc reasoning","Granularity","The loop"],answer:0,explanation:"The story machine cannot stand a blank page.",concept:"Narrative brain"},{kind:"mcq",question:"Building reasons after an emotional verdict is…",options:["Post-hoc reasoning","Confabulation","Labelling","Encoding"],answer:0,explanation:"The press release follows the decision.",concept:"Post-hoc reasoning"},{kind:"mcq",question:"Which shows the highest emotional granularity?",options:['"I’m overlooked, not just bad"','"I’m fine"','"I feel bad"','"Whatever"'],answer:0,explanation:"Precision in naming points to precision in action.",concept:"Emotional granularity"},{kind:"mcq",question:"The thought–feeling–action loop shows that…",options:["Each element feeds the next in a cycle","Only thoughts matter","Feelings cannot change","Actions are irrelevant"],answer:0,explanation:"Three handles, one loop. Action is often the fastest door.",concept:"The thought–feeling–action loop"},{kind:"truefalse",question:"Confabulators know their stories are invented.",options:["True","False"],answer:1,explanation:"Confabulation is sincere. That is what makes it powerful.",concept:"Narrative brain"},{kind:"truefalse",question:"A core belief usually forms from a single event overnight.",options:["True","False"],answer:1,explanation:"Roots grow slowly from repeated experience.",concept:"Beliefs vs. thoughts"},{kind:"scenario",question:'After a bad meeting you skip the gym and think "I’m off track." The fastest loop entry point is…',options:["The action: go for a 10-minute walk","The thought: demand it vanish","The feeling: pretend it is not there","None; loops cannot be broken"],answer:0,explanation:"Small action first. It feeds back into thought and feeling.",concept:"The thought–feeling–action loop"}],share:{hook:"You can see the machinery behind a mood.",question:"Which of the week’s five ideas will you practise this weekend?",posts:{reflective:"Three weeks of Uneek Academy’s psychology course. This week mapped the roots: beliefs under thoughts, the story machine filling gaps, feelings hiring reasons, precise names for feelings, and the loop that runs all three. The image that sticks: thoughts are leaves, beliefs are roots. I have been pruning leaves for years. The loop model gives me doors instead of walls. One more month of foundations to go — and a weak-topic list that is getting shorter. Which of the five ideas will you practise this weekend?",direct:"Week 3 of Uneek Academy’s psychology course done. Takeaways: beliefs drive thoughts; the brain confabulates; verdicts come before reasons; precise feeling-words give precise actions; thoughts–feelings–actions run in a loop with three doors. Practical result: less spiralling, more options. The exam found my weak spot (post-hoc reasoning vs confabulation) and it is queued for review. Which of the five ideas will you practise this weekend?",story:'Tonight I mapped a mood on paper: the thought, the feeling, the action, and the arrow pointing back. Day 19’s exercise, three weeks into Uneek Academy’s psychology course. Seeing the loop drawn made it hard to keep believing "that’s just how I am." There are three doors in that diagram. This week also taught me that my confident stories are fiction and my feelings hire press-release writers. Not flattering. Very useful. Which of the five ideas will you practise this weekend?'}}},{id:"psy-d21",month:1,week:3,day:7,dayIndex:21,type:"rest",title:"Rest Day",duration:"1 min",summary:"Rest is part of the program, not a break from it.",concepts:[],cards:[],questions:[],restMessage:"Three weeks is real momentum. Today, rest is the work. Whatever you do, do it slowly. Tick rest and the streak continues.",share:{hook:"Rest is where learning settles.",posts:{reflective:"",direct:"",story:""}}},{id:"psy-d22",month:1,week:4,day:1,dayIndex:22,type:"reading",title:"Schemas: The Mind’s Filing System",duration:"7 min",summary:"Schemas are folders the mind builds to make the world fast to read — until it stops reading and just files.",concepts:["Schemas","Mental models","When schemas mislead"],tryOn:"Name three schemas you use daily (types of people, places, situations). For one, write a single line: how it helps, and how it could mislead. Timid version: use fictional characters first.",cards:[{kind:"hook",body:"Your mind does not meet the world raw. It meets a filing system."},{kind:"text",title:"Folders for everything",body:'A schema is a mental structure that organises knowledge: "restaurant," "first date," "my manager." Schemas make life navigable. The cost: once a folder exists, new information gets filed into it faster than it gets examined.'},{kind:"definition",title:"Schema",body:"A mental folder of expectations about a type of person, place, or situation."},{kind:"example",title:"Everyday example",body:'Your "quiet person" schema files a quiet colleague as shy. Then a meeting reveals they are fierce in debate. If the schema updates, good. If you think "they’re pretending," the folder just defended itself against reality.'},{kind:"practice",title:"Practice task",body:"Name three schemas you use daily (types of people, places, situations). For one of them, write one way it helps and one way it could mislead."}],questions:[{kind:"mcq",question:"A schema is…",options:["A mental folder of expectations","A feeling","A memory error","A logical rule"],answer:0,explanation:"Organised expectations that make the world fast to navigate.",concept:"Schemas"},{kind:"truefalse",question:"Schemas save time but can filter out contradicting evidence.",options:["True","False"],answer:0,explanation:"Fast filing, slow updating. That is the trade.",concept:"When schemas mislead"},{kind:"scenario",question:"New evidence contradicts your schema and you explain it away. What happened?",options:["The schema defended itself against reality","The evidence was worthless","Your memory failed","Nothing unusual"],answer:0,explanation:"Folders protect their contents. Healthy minds update folders anyway.",concept:"Mental models"}],share:{hook:"Your mind does not meet the world raw. It meets a filing system.",question:"Which schema of yours is overdue for an update?",posts:{reflective:'Day 22 of Uneek Academy’s psychology course: schemas — the mind’s filing system. Folders like "quiet person" or "first date" make the world navigable and fast. The cost: reality gets filed before it gets examined. When evidence contradicts the folder, the folder defends itself ("they’re pretending"). The exercise: name three daily schemas and find where each helps and misleads. Mine around "serious people" needs an update. Which schema of yours is overdue for one?',direct:'Your mind files the world into folders. Day 22 of Uneek Academy’s psychology course: schemas — "restaurant," "my manager," "quiet person" — make life fast and predictable. Downside: new information gets filed before it gets examined, and folders defend themselves against evidence. Task: name three schemas and spot where each misleads. Mine around "serious people" is overdue for an update. Which of yours is?',story:'I had a neat folder labelled "quiet guy from finance." Last week he dismantled a bad plan in thirty seconds and my folder refused to update: "he’s showing off." Day 22 named it — schemas. The mind’s filing system, brilliant at speed and stubborn against reality. I listed three of my folders today and found one doing real damage around "serious people." Folders should serve the data, not the other way round. Which schema of yours is overdue for an update?'}}},{id:"psy-d23",month:1,week:4,day:2,dayIndex:23,type:"video",title:"Cognitive Load: Why You Feel Stuck",duration:"8 min",summary:'Working memory is small. Overload it and you do not get "busy" — you get stuck.',concepts:["Working memory","Cognitive load","Overwhelm management"],tryOn:'Do a 2-minute "desk dump": write every open loop on one page, then do one item for 5 minutes. Timid version: the dump is private — no one sees the list.',cards:[{kind:"hook",body:"Your working memory holds about four things. Modern life hands you forty."},{kind:"text",title:"The tiny desk",body:"Think of working memory as a small desk. It holds a few items at a time — a plan, a worry, a message to reply to. Every open loop occupies a slot. Fill the desk and thinking does not slow gracefully; it jams. That jam is what overwhelm feels like from the inside."},{kind:"definition",title:"Cognitive load",body:"How much your working memory is holding at once. Near its limit, everything gets harder."},{kind:"example",title:"Everyday example",body:"Cooking while arguing while checking messages: one burns. Not because you are careless — the desk was full. The fix is not willpower; it is fewer items on the desk (write them down) and fewer at once (serialise)."},{kind:"practice",title:"Practice task",body:'When you feel stuck today, do a "desk dump": write every open loop on paper within two minutes. The point is not organisation — it is offloading the desk.'}],questions:[{kind:"mcq",question:"Working memory is…",options:["A small mental desk holding a few items at once","Unlimited storage","Long-term memory","Emotional memory only"],answer:0,explanation:"Few slots. Many demands. The math explains a lot of bad days.",concept:"Working memory"},{kind:"truefalse",question:"When cognitive load is too high, thinking just speeds up to cope.",options:["True","False"],answer:1,explanation:"It jams. Overwhelm is a desk with too much on it.",concept:"Cognitive load"},{kind:"scenario",question:"You are juggling messages, cooking, and a phone call and something burns. Best fix?",options:["Reduce what is on the desk: one task at a time, write the rest down","Try harder to hold everything","Blame your memory","Do everything faster"],answer:0,explanation:"Load is managed by offloading and sequencing, not by willpower.",concept:"Overwhelm management"}],share:{hook:"Your working memory holds about four things. Modern life hands you forty.",question:"What would you take off your desk today if you could?",posts:{reflective:'Day 23 of Uneek Academy’s psychology course: working memory is a tiny desk — about four slots — and each open loop occupies one. Fill it and thinking jams; that jam is what overwhelm actually is. Not a character flaw. An accounting problem. The exercise: a two-minute "desk dump" of every open loop. Eleven items. No wonder the day felt slow. The fix is offloading and sequencing, not willpower. What would you take off your desk today if you could?',direct:"Overwhelm is not a mood. It is an accounting problem. Day 23 of Uneek Academy’s psychology course: working memory holds ~4 items; each open loop takes a slot. Over the limit, thinking jams. Fix: desk-dump every open loop onto paper (two minutes) and do one thing at a time. I dumped eleven items today and instantly felt lighter. Not softer — smarter. What would you take off your desk today if you could?",story:'I was "busy" for three hours and produced nothing. Day 23 of the course explained it: my working-memory desk had fourteen items on it — emails, a worry, a plan, a message I owed. The desk jammed; that is what overwhelm is. I did the exercise: two-minute dump, everything on paper. Eleven items. Then one thing. The day restarted. What would you take off your desk today if you could?'}}},{id:"psy-d24",month:1,week:4,day:3,dayIndex:24,type:"interactive",title:"The Mind–Body Connection",duration:"7 min",summary:"The body is not a taxi for the brain. Breathing, posture, sleep, and movement change how you think.",concepts:["Physiology and cognition","Breathing","Sleep and the mind"],tryOn:"Run one body-first reset before something stressful: 10 slow breaths (out longer than in) or a 5-minute walk. Note before/after in one word each.",cards:[{kind:"hook",body:"The mind lives in a body. Treat the body well and the mind gets cheaper to run."},{kind:"text",title:"Two-way street",body:"Thoughts change the body (a worrying sentence raises your heart rate). The body changes the mind (slow breathing steadies attention; poor sleep wrecks judgement). Psychology keeps rediscovering that the fastest route to a calmer mind sometimes runs through the lungs."},{kind:"definition",title:"Physiological regulation",body:"Using the body — breath, movement, sleep — to change your mental state."},{kind:"example",title:"Everyday example",body:"Before a hard conversation, your stomach tightens and your thoughts race. Ten slow breaths do not fix the problem — but they widen the gap between trigger and reaction. Wider gap, better choices."},{kind:"practice",title:"Practice task",body:"Do one physiological reset today: 10 slow breaths (out longer than in), a 5-minute walk, or a real lunch break away from screens. Notice the before and after."}],questions:[{kind:"mcq",question:"The mind–body connection means that…",options:["Body states and mental states influence each other","Only the mind matters","Bodies are irrelevant to thought","Thinking is purely mechanical"],answer:0,explanation:"Two-way traffic. The body is a lever on the mind.",concept:"Physiology and cognition"},{kind:"truefalse",question:"Slow breathing can steady attention before a hard conversation.",options:["True","False"],answer:0,explanation:"It widens the gap between trigger and reaction. The gap is where choice lives.",concept:"Breathing"},{kind:"scenario",question:"After two nights of poor sleep you make a hasty decision. Which concept explains it best?",options:["Sleep and the mind — rested cognition judges better","Heuristics only","Confabulation","Inattentional blindness"],answer:0,explanation:"Sleep is cognitive infrastructure, not downtime.",concept:"Sleep and the mind"}],share:{hook:"The fastest route to a calmer mind sometimes runs through the lungs.",question:"What is one body-first reset that works for you?",posts:{reflective:"Day 24 of Uneek Academy’s psychology course: the mind lives in a body. Slow breathing steadies attention; sleep is cognitive infrastructure; movement changes mood before thoughts do. The reframe is practical — not every problem needs a thought. Some need a walk, a meal, or ten breaths with a longer exhale. I tried the reset before a difficult call and the gap between trigger and reaction widened just enough to choose better words. What is one body-first reset that works for you?",direct:"Not every problem needs a thought. Some need a breath. Day 24 of Uneek Academy’s psychology course: body and mind run two-way traffic — slow breathing steadies attention, poor sleep wrecks judgement, movement changes mood fast. Before a hard conversation, ten slow breaths (longer exhale) widen the gap between trigger and reaction. That gap is where your options live. What is one body-first reset that works for you?",story:"I nearly sent a sharp reply at 11pm after two bad nights of sleep. Instead I remembered day 24’s lesson — the mind lives in a body — and closed the laptop. Morning, breakfast, a walk, then the reply. Same facts, kinder sentence, better outcome. Sleep is infrastructure; breath is a lever; the body is not just a taxi for the brain. What is one body-first reset that works for you?"}}},{id:"psy-d25",month:1,week:4,day:4,dayIndex:25,type:"reading",title:"Your First Psychology Toolkit",duration:"7 min",summary:"Four weeks of tools, one page. Catch → name → check → act. The whole month in one small routine.",concepts:["Integration","The catch-name-check-act routine","Deliberate practice"],tryOn:"Run the full four steps once today — catch, name, check, act — and write the four lines. The situation can be tiny: a delayed message is perfect practice.",exercise:"Use the full routine once today: catch a thought, name the feeling precisely, check the story, act small. Write down the four steps.",cards:[{kind:"hook",body:"Catch it. Name it. Check it. Act small. That is Month 1 in four words."},{kind:"text",title:"The routine",body:"Catch the automatic thought (Week 2). Name the feeling precisely (Week 3). Check the story: what is the evidence, what would I tell a friend (Weeks 1–3). Act small: one behaviour that feeds a better loop (Week 3). Four steps, portable anywhere."},{kind:"definition",title:"Catch–name–check–act",body:"A four-step routine: notice the thought, name the feeling, check the story, take one small action."},{kind:"example",title:"Everyday example",body:'A meeting invite lands with no agenda. Catch: "Something’s wrong." Name: anxiety, not "bad." Check: three invites this month had no agenda; nothing was wrong. Act: reply asking what to prepare. Four minutes, whole spiral defused.'},{kind:"practice",title:"Practice task",body:"Run today’s exercise with the complete routine. Write all four steps. Repetition makes the sequence automatic — and autopilot with good tools is exactly what we want."}],questions:[{kind:"mcq",question:"What is the correct order of the routine?",options:["Catch → name → check → act","Act → check → name → catch","Name → catch → act → check","Check → act → catch → name"],answer:0,explanation:"Notice, label, examine, move.",concept:"The catch-name-check-act routine"},{kind:"mcq",question:'"Name" in the routine refers to…',options:["Naming the feeling precisely","Naming the other person","Naming the thought’s author","Nothing; it is a filler step"],answer:0,explanation:"Emotional granularity: specific name, specific next step.",concept:"Integration"},{kind:"scenario",question:"You use the routine and the story still looks true. What then?",options:["Act small on it — some stories are accurate and need a response","Assume the routine failed",'Repeat "catch" forever',"Ignore the situation"],answer:0,explanation:"The goal is accuracy and options, not forced positivity.",concept:"Deliberate practice"}],share:{hook:"Catch it. Name it. Check it. Act small.",question:"What problem could you take through the four steps today?",posts:{reflective:"Day 25 of Uneek Academy’s psychology course assembled the whole first month into one routine: catch the thought, name the feeling precisely, check the story against evidence, act small. I ran it on a meeting invite with no agenda and watched a mild spiral dissolve in four minutes. Not positive thinking — accurate thinking with options at the end. Tomorrow is the month review; today the routine went from notes to something I can actually do. What problem could you take through the four steps today?",direct:'Month 1 of Uneek Academy’s psychology course in four words: catch, name, check, act. Catch the automatic thought. Name the feeling precisely. Check the story against evidence. Act small. Four steps, portable, repeatable. Used it today on an ambiguous invite — dissolved in minutes. This is what "tools" means: not notes you reread, routines you run. What problem could you take through the four steps today?',story:'A vague calendar invite appeared and my stomach dropped: "they’re going to reassign the project." Day 25 of the course handed me the full routine. Catch: that sentence. Name: anxiety. Check: evidence? One missing agenda. Act: reply asking what to prepare. Total time, four minutes. Four weeks ago that sentence would have run my afternoon. Catch, name, check, act — Month 1, compressed. What problem could you take through the four steps today?'}}},{id:"psy-d26",month:1,week:4,day:5,dayIndex:26,type:"reading",title:"Foundations in Action: A Day of Noticing",duration:"6 min",summary:"Your last learning day of Month 1 is a field trip: one full day of watching the machinery you have studied.",concepts:["Applied observation","Integration","Month 1 capstone"],tryOn:"Field-report day: five observations, one per concept, one line each. Timid version: all five can come from watching other people — the skill is the same.",exercise:"A noticing day: collect five observations (one per concept: autopilot, perception, attention, a shortcut, a thought–feeling–action loop). One line each. That is your Month 1 field report.",cards:[{kind:"hook",body:"Psychology you do not use is trivia. Today, use all of it."},{kind:"text",title:"A day of noticing",body:"For one day, watch for the five machineries from Month 1: autopilot running a routine, perception editing reality, attention missing the gorilla, a shortcut judging on thin evidence, a loop running a mood. You are not fixing anything today. You are collecting field data."},{kind:"example",title:"Everyday example",body:'A field report might read: "Missed the turn (autopilot). Assumed the text was rude (story machine). Got angry then justified it (press release). Named it as overlooked, not bad (granularity). Walked before replying (action first)." Five lines. One person. One day.'},{kind:"practice",title:"Practice task",body:"Today’s exercise is the capstone: five observations, one per concept, one line each. Tomorrow’s review will ask what you found."}],questions:[{kind:"mcq",question:"The purpose of a noticing day is to…",options:["Collect field data on the machinery without fixing anything","Prove the concepts wrong","Replace the weekly review","Earn extra XP for speed"],answer:0,explanation:"Observation first. Change follows what you can see.",concept:"Applied observation"},{kind:"truefalse",question:"On the noticing day you must correct every bias you spot.",options:["True","False"],answer:1,explanation:"Seeing is the task. Correcting comes later, and gently.",concept:"Applied observation"},{kind:"mcq",question:"Which belongs in a field report line?",options:['"Assumed the text was rude (story machine)"','"I am a bad person"','"Psychology is useless"','"Nothing happened"'],answer:0,explanation:"Observation + concept tag. Specific, short, non-judgemental.",concept:"Integration"}],share:{hook:"Psychology you do not use is trivia.",question:"What is one observation from your own noticing day?",posts:{reflective:'Final learning day of Month 1 in Uneek Academy’s psychology course: a noticing day. Five observations, one per concept — autopilot, perception, attention, a shortcut, a loop. Mine found all five by lunch. The most useful line: "assumed the text was rude (story machine)." No fixing today, just field data. A month ago I would have called all of this "just how I think." Now I can point at the machinery. What is one observation from your own noticing day?',direct:'Psychology you do not use is trivia. Last day of Month 1 in Uneek Academy’s psychology course is a field trip: collect five observations across the five concepts. Mine found all five before lunch. The point is seeing, not fixing. A month in, "just how I am" has become "which system is running?" That is the upgrade. What is one observation from your own noticing day?',story:'Today I watched my own mind like a field researcher. 8:40 — missed my exit (autopilot). 10:15 — decided a text was curt (story machine). 12:00 — got angry first, built reasons after (press release). 2:30 — renamed "bad" to "overlooked" (granularity). 4:00 — skipped the task, felt worse, noticed the loop. Five observations, Month 1 of Uneek Academy complete. The machinery is visible now. What is one observation from your own noticing day?'}}},{id:"psy-d27",month:1,week:4,day:6,dayIndex:27,type:"review",title:"Month 1 Review: Foundations of the Mind",duration:"12 min",summary:"The full month in one test: perception, attention, memory, thoughts, feelings, and the loops between them.",concepts:["Month 1 synthesis"],tryOn:'Retell the whole Month 1 map to one person — or record a 2-minute voice note for yourself. End with: "What changed in how I listen?"',reviewTopics:["What psychology is","Automatic processing & perception","Attention & heuristics","Memory & encoding","Thoughts, beliefs & the loop","Emotional granularity & regulation"],cards:[{kind:"hook",body:"One month ago these were ideas. Now they are things you have watched happen inside your own head."},{kind:"list",title:"The whole map",items:["The mind runs mostly on automatic processing; attention is a spotlight.","Perception constructs reality from expectations; shortcuts judge fast.","Memory rebuilds; encoding needs attention; forgetting is housekeeping.","Thoughts are sentences on top of beliefs; the story machine fills gaps.","Feelings and thoughts split into two handles; loops give three doors.","The toolkit: catch → name → check → act."]},{kind:"text",title:"What changes next",body:"Month 2 asks why people think the way they do — biases, beliefs, culture, identity. Everything you learned this month is the vocabulary for it."}],questions:[{kind:"mcq",question:"Which pair is correctly matched?",options:["Perception: construction from input + expectations","Memory: perfect recording","Attention: unlimited resource","Heuristics: slow, exact rules"],answer:0,explanation:"The brain builds, edits, and shortcuts its way through the world.",concept:"Automatic processing & perception"},{kind:"mcq",question:"The fastest way to rescue an overloaded mind is…",options:["Offload the desk: write open loops down and do one thing at a time","Try harder to remember everything","Scroll for a while","Sleep at the desk"],answer:0,explanation:"Cognitive load is an accounting problem; offload and sequence.",concept:"Thoughts, beliefs & the loop"},{kind:"mcq",question:'"I feel like they don’t respect me" should first be split into…',options:['A feeling (anger/hurt) and a thought ("they don’t respect me")',"Two feelings","Two thoughts","Nothing; it is already precise"],answer:0,explanation:"Two objects, two treatments. Split before solving.",concept:"Emotional granularity & regulation"},{kind:"mcq",question:"Which is a retrieval failure?",options:["Tip-of-the-tongue for a name","A memory that never got encoded","A belief","A heuristic"],answer:0,explanation:"The file is there; the cue is missing.",concept:"Memory & encoding"},{kind:"mcq",question:'The "invisible gorilla" demonstrates…',options:["Selective attention: busy focus makes visible things invisible","Poor eyesight","Memory decay","Confabulation"],answer:0,explanation:"Attention is a spotlight with a narrow beam.",concept:"Attention & heuristics"},{kind:"truefalse",question:"Psychology is the careful study of thoughts, feelings, and behaviour.",options:["True","False"],answer:0,explanation:"Observed, tested, and revised — that is the method.",concept:"What psychology is"},{kind:"truefalse",question:"Confabulated stories are told as deliberate lies.",options:["True","False"],answer:1,explanation:"Sincere fiction from the story machine.",concept:"Thoughts, beliefs & the loop"},{kind:"truefalse",question:"Schemas can filter out evidence that contradicts them.",options:["True","False"],answer:0,explanation:"Folders defend contents; wise minds update folders.",concept:"Thoughts, beliefs & the loop"},{kind:"scenario",question:"A friend is harsh after a bad night’s sleep. Using Month 1, your first interpretation is…",options:["Cognitive load and the mind–body connection: sleep loss degrades judgement","They dislike you","Their true character is showing","Nothing to do with psychology"],answer:0,explanation:'Physiology and load explain a lot of "personal" behaviour.',concept:"Thoughts, beliefs & the loop"},{kind:"scenario",question:'Using catch–name–check–act on "I’ll fail this test", the "check" step is…',options:["Asking what the evidence is and what I would tell a friend","Feeling worse about it","Ignoring the thought","Acting immediately"],answer:0,explanation:"Check = examine the story with evidence and perspective.",concept:"Thoughts, beliefs & the loop"}],share:{hook:"What was theory a month ago is now something you have watched happen.",question:"What is the biggest change you have noticed in yourself this month?",posts:{reflective:'Month 1 of Uneek Academy’s psychology course complete. Four weeks ago, "attention is a spotlight" was a phrase. Now it is something I have watched — mid-conversation, rehearsing instead of listening. The month built a full map: autopilot, construction, shortcuts, rebuildable memory, sentences over beliefs, loops with three doors. The toolkit is four words: catch, name, check, act. I am not calmer because life got easier. I am calmer because the machinery is visible. What is the biggest change you have noticed in yourself this month?',direct:'Month 1 done: Foundations of the Mind, Uneek Academy. The full map — perception constructs, attention spots, shortcuts judge, memory rebuilds, thoughts narrate, feelings and thoughts split, loops run. Toolkit: catch, name, check, act. Twenty-six learning days, four reviews, four rests. Score is in; weak topics queued. Biggest upgrade: "just how I am" is now "which system is running?" What is the biggest change you have noticed in yourself this month?',story:'Tonight I reread my field notes from the noticing day: "assumed the text was rude (story machine)," "got angry first, justified later (press release)," "renamed bad → overlooked (granularity)." Four weeks of Uneek Academy’s psychology course, and the distance between those lines and how I would have described myself a month ago is enormous. Not a new personality — a visible machinery and four words: catch, name, check, act. On to Month 2. What is the biggest change you have noticed in yourself this month?'}}},{id:"psy-d28",month:1,week:4,day:7,dayIndex:28,type:"rest",title:"Rest Day",duration:"1 min",summary:"Rest is part of the program, not a break from it.",concepts:[],cards:[],questions:[],restMessage:"Month 1 is complete. The best thing you can do for your memory today is nothing at all. Rest, and let it settle. Tick rest to keep the streak.",share:{hook:"Rest is where learning settles.",posts:{reflective:"",direct:"",story:""}}}];function a(e,t){return s(e).find(e=>e.dayIndex===t)}function s(e){return"psychology"===e?i:"communication"===e?n:[]}},5552:function(e,t,o){o.d(t,{Ol:function(){return i},XR:function(){return r},im:function(){return s},mF:function(){return a},sH:function(){return h}});let n=[{month:1,name:"Indigo",hex:"#4F46E5",text:"white"},{month:2,name:"Violet",hex:"#8B5CF6",text:"white"},{month:3,name:"Teal",hex:"#14B8A6",text:"ink"},{month:4,name:"Sky",hex:"#0EA5E9",text:"ink"},{month:5,name:"Orange",hex:"#FF7A45",text:"ink"},{month:6,name:"Amber",hex:"#FFB020",text:"ink"}],i={slug:"psychology",title:"Psychology: How People Think",tagline:"Understand people. Read situations. Connect without pretending.",description:"A six-month daily program that takes a complete beginner to a confident, practical understanding of how people think, decide, and communicate — including how to read situations and reach guarded people with respect, not tricks.",level:"Beginner to advanced",totalWeeks:26,totalDays:182,levelTitles:[{title:"Observer",xp:0},{title:"Analyst",xp:500},{title:"Reader",xp:1500},{title:"Strategist",xp:3e3},{title:"Expert",xp:5e3}],months:[{title:"Foundations of the Mind",weeks:4,topics:"What psychology is, brain basics, perception, attention, memory, how thoughts form, emotions vs. thoughts.",accent:"#4F46E5",accentText:"white"},{title:"Why People Think the Way They Do",weeks:4,topics:"Cognitive biases, mental shortcuts, beliefs and worldview, upbringing and culture, habits and identity.",accent:"#8B5CF6",accentText:"white"},{title:"Personality and Reading People",weeks:5,topics:"Personality models, temperament, motivation and needs, body language, tone, micro-expressions (with honest limits).",accent:"#14B8A6",accentText:"ink"},{title:"Communication and Connection",weeks:4,topics:"Active listening, questioning, framing, rapport, empathy, finding someone’s mental framework through conversation.",accent:"#0EA5E9",accentText:"ink"},{title:"Influence and Difficult People",weeks:5,topics:"Persuasion principles, resistance and defensiveness, approaching guarded people, handling conflict, emotional regulation, ethics of influence.",accent:"#FF7A45",accentText:"ink"},{title:"Mastery and Application",weeks:4,topics:"Group psychology, decision-making, social dynamics, case studies, a capstone project, final assessment.",accent:"#FFB020",accentText:"ink"}],status:"live",coverIllustration:"brain",coverImage:"/images/course-psychology.jpg"},a=[{slug:"communication",title:"Communication: Say It So It Lands",tagline:"Clarity, presence, and words that work in real rooms — built for quiet people.",description:"A daily program on speaking clearly, listening deeply, and handling hard conversations — with exact words to borrow, tiny brave actions every day, and a rhythm designed for timid speakers. Same weekly engine as Psychology: five learn days, one review, one rest.",level:"Beginner to intermediate",totalWeeks:16,totalDays:112,levelTitles:[{title:"Beginner",xp:0},{title:"Speaker",xp:600},{title:"Connector",xp:1800},{title:"Communicator",xp:3600}],months:[{title:"Foundations of Clear Speech",weeks:4,topics:"Speaking anxiety and the spotlight effect, the 3-second pause, clarity and structure (What–So What–Now What), micro-bravery scripts for timid speakers, message vs. reception in writing.",accent:"#14B8A6",accentText:"ink"},{title:"Listening and Rapport",weeks:4,topics:"Active listening that people can feel, questions that open doors, small talk without panic, remembering names, reading rooms, warmth without performance.",accent:"#0EA5E9",accentText:"ink"},{title:"Difficult Conversations",weeks:4,topics:"Saying no without guilt, boundaries with exact sentences, handling criticism, disagreeing kindly, repair after conflict, staying calm when it is personal.",accent:"#FF7A45",accentText:"ink"},{title:"Presence and Influence",weeks:4,topics:"Storytelling that lands, speaking to groups without shrinking, persuasion with integrity, interviews and pitches, a capstone: the conversation you have been avoiding.",accent:"#FFB020",accentText:"ink"}],status:"live",coverIllustration:"speech",coverImage:"/images/course-communication.jpg"},{slug:"finance",title:"Personal Finance: Money With Intention",tagline:"Build calm, durable money habits one small lesson a day.",description:"Budgeting, saving, investing basics, and the psychology of spending — practical, jargon-free, and paced for real life.",level:"Beginner",totalWeeks:12,totalDays:84,levelTitles:[{title:"Starter",xp:0},{title:"Planner",xp:500},{title:"Builder",xp:1500}],months:[{title:"Money Basics",weeks:4,topics:"Cash flow, habits, goals, simple investing.",accent:"#FFB020",accentText:"ink"}],status:"coming_soon",coverIllustration:"coins",coverImage:"/images/course-finance.jpg"}],s=[i,...a];function r(e){return s.find(t=>t.slug===e)}function h(e){return n[(e-1)%n.length]}}}]);